import {ReentrancyGuard} from "@oz/utils/ReentrancyGuard.sol";
import {Joule} from "./Joule.sol";

interface ITerawhirr {
    function ownerOf(uint256 id) external view returns (address);
    function transferFrom(address from, address to, uint256 id) external;
    function hashrateOf(uint256 id) external view returns (uint256);
    function levelOf(uint256 id) external view returns (uint8);
    function levelUp(uint256 id) external returns (uint8);
}

/// @title Whirr Mine — stake TERAWHIRR rigs, mine JOULE every block, burn JOULE to upgrade, sell JOULE back to the pool.
/// - Emission: `perBlock0` JOULE per block shared by all staked hashrate, halving every `halvingBlocks` blocks.
/// - Upgrade sink: level L -> L+1 burns upgradeBase * (L+1)^2 JOULE and adds +25% of the rig's base hashrate (max level 8).
/// - Redeem pool: BNB sent here by the NFT on every paid mint. Anyone can burn JOULE for a pro-rata share of the pool:
///   out = pool * amount / JOULE supply * (1 - exitBps). The exit fee stays in the pool for remaining holders.
/// There is NO owner and NO admin function: nobody can withdraw the pool, pause mining or move staked rigs.
contract WhirrMine is ReentrancyGuard {
    ITerawhirr public immutable nft;
    Joule public immutable joule;
    uint256 public immutable startBlock;
    uint256 public immutable perBlock0;
    uint256 public immutable halvingBlocks;
    uint256 public immutable upgradeBase;
    uint16 public immutable exitBps;
    uint256 private constant ACC = 1e18;

    uint256 public totalHash;
    uint256 public accPerHash;
    uint256 public lastBlock;
    uint256 public totalRedeemedBNB;
    uint256 public totalBurnedUpgrade;

    mapping(address => uint256) public hashOf;
    mapping(address => uint256) internal debt;
    mapping(address => uint256) internal owed;
    mapping(address => uint256) public rigsOf;
    mapping(uint256 => address) public stakerOf;
    mapping(uint256 => uint256) public stakedHash;

    event Funded(address indexed from, uint256 amount);
    event Staked(address indexed user, uint256 id, uint256 hashrate);
    event Unstaked(address indexed user, uint256 id);
    event Claimed(address indexed user, uint256 amount);
    event Upgraded(address indexed user, uint256 id, uint8 level, uint256 burned, uint256 hashrate);
    event Redeemed(address indexed user, uint256 burned, uint256 bnbOut);

    constructor(address nft_, uint256 perBlock0_, uint256 halvingBlocks_, uint256 upgradeBase_, uint16 exitBps_,
        string memory tokenName, string memory tokenSymbol) {
        require(nft_ != address(0) && halvingBlocks_ > 0 && exitBps_ < 10000, "params");
        nft = ITerawhirr(nft_);
        perBlock0 = perBlock0_; halvingBlocks = halvingBlocks_; upgradeBase = upgradeBase_; exitBps = exitBps_;
        startBlock = block.number; lastBlock = block.number;
        joule = new Joule(tokenName, tokenSymbol);
    }

    // ---------------- redeem pool ----------------
    function fund() external payable { emit Funded(msg.sender, msg.value); }
    receive() external payable { emit Funded(msg.sender, msg.value); }

    function poolBalance() public view returns (uint256) { return address(this).balance; }

    function quoteRedeem(uint256 amount) public view returns (uint256) {
        uint256 s = joule.totalSupply();
        if (amount == 0 || s == 0 || amount > s) return 0;
        return address(this).balance * amount / s * (10000 - exitBps) / 10000;
    }

    function redeem(uint256 amount, uint256 minOut) external nonReentrant returns (uint256 out) {
        out = quoteRedeem(amount);
        require(out > 0 && out >= minOut, "out");
        joule.burnFrom(msg.sender, amount);          // reverts if the caller lacks the JOULE
        totalRedeemedBNB += out;
        (bool ok,) = msg.sender.call{value: out}("");
        require(ok, "send");
        emit Redeemed(msg.sender, amount, out);
    }

    // ---------------- emission ----------------
    function rateAt(uint256 blk) public view returns (uint256) {
        if (blk < startBlock) return 0;
        uint256 era = (blk - startBlock) / halvingBlocks;
        return era >= 64 ? 0 : perBlock0 >> era;
    }

    function emittedBetween(uint256 a, uint256 b) public view returns (uint256 total) {
        if (a < startBlock) a = startBlock;
        while (a < b) {
            uint256 era = (a - startBlock) / halvingBlocks;
            if (era >= 64) break;
            uint256 end = startBlock + (era + 1) * halvingBlocks;
            uint256 seg = (b < end ? b : end) - a;
            total += seg * (perBlock0 >> era);
            a += seg;
        }
    }

    function _update() internal {
        if (block.number <= lastBlock) return;
        if (totalHash > 0) accPerHash += emittedBetween(lastBlock, block.number) * ACC / totalHash;
        lastBlock = block.number;
    }

    function _settle(address u) internal { owed[u] += hashOf[u] * accPerHash / ACC - debt[u]; }
    function _sync(address u) internal { debt[u] = hashOf[u] * accPerHash / ACC; }

    function pending(address u) public view returns (uint256) {
        uint256 acc = accPerHash;
        if (block.number > lastBlock && totalHash > 0) acc += emittedBetween(lastBlock, block.number) * ACC / totalHash;
        return owed[u] + hashOf[u] * acc / ACC - debt[u];
    }

    /// JOULE per block a wallet earns right now
    function userRate(address u) external view returns (uint256) {
        return totalHash == 0 ? 0 : rateAt(block.number) * hashOf[u] / totalHash;
    }

    // ---------------- staking ----------------
    function stake(uint256[] calldata ids) external nonReentrant {
        require(ids.length > 0 && ids.length <= 50, "ids");
        _update(); _settle(msg.sender);
        uint256 add;
        for (uint256 i; i < ids.length; ++i) {
            uint256 id = ids[i];
            require(nft.ownerOf(id) == msg.sender, "not yours");
            nft.transferFrom(msg.sender, address(this), id);
            uint256 h = nft.hashrateOf(id);
            stakerOf[id] = msg.sender; stakedHash[id] = h; add += h;
            emit Staked(msg.sender, id, h);
        }
        hashOf[msg.sender] += add; totalHash += add; rigsOf[msg.sender] += ids.length;
        _sync(msg.sender);
    }

    function unstake(uint256[] calldata ids) external nonReentrant {
        require(ids.length > 0 && ids.length <= 50, "ids");
        _update(); _settle(msg.sender);
        uint256 sub;
        for (uint256 i; i < ids.length; ++i) {
            uint256 id = ids[i];
            require(stakerOf[id] == msg.sender, "not your stake");
            sub += stakedHash[id];
            delete stakerOf[id]; delete stakedHash[id];
            emit Unstaked(msg.sender, id);
        }
        hashOf[msg.sender] -= sub; totalHash -= sub; rigsOf[msg.sender] -= ids.length;
        _sync(msg.sender);
        for (uint256 i; i < ids.length; ++i) nft.transferFrom(address(this), msg.sender, ids[i]);
    }

    function claim() public nonReentrant returns (uint256 amt) {
        _update(); _settle(msg.sender); _sync(msg.sender);
        amt = owed[msg.sender];
        if (amt > 0) { owed[msg.sender] = 0; joule.mint(msg.sender, amt); emit Claimed(msg.sender, amt); }
    }

    // ---------------- upgrade (JOULE sink) ----------------
    function upgradeCost(uint256 id) public view returns (uint256) {
        uint256 n = uint256(nft.levelOf(id)) + 1;
        return upgradeBase * n * n;
    }

    function upgrade(uint256 id) external nonReentrant {
        address staker = stakerOf[id];
        require(staker == msg.sender || (staker == address(0) && nft.ownerOf(id) == msg.sender), "not yours");
        uint256 cost = upgradeCost(id);
        joule.burnFrom(msg.sender, cost);
        totalBurnedUpgrade += cost;
        uint8 lvl;
        if (staker != address(0)) {
            _update(); _settle(staker);
            uint256 old = stakedHash[id];
            lvl = nft.levelUp(id);
            uint256 h = nft.hashrateOf(id);
            stakedHash[id] = h;
            hashOf[staker] = hashOf[staker] - old + h;
            totalHash = totalHash - old + h;
            _sync(staker);
        } else {
            lvl = nft.levelUp(id);
        }
        emit Upgraded(msg.sender, id, lvl, cost, nft.hashrateOf(id));
    }
}

