// ==== src/RaidBoss.sol ====
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@oz/utils/ReentrancyGuard.sol";

interface IRogueNFT {
    function ownerOf(uint256) external view returns (address);
    function totalSupply() external view returns (uint32);
    function statsOf(uint256) external view returns (uint256 atk, uint256 crit);
}

interface IShard {
    function mint(address, uint256) external;
    function raidBurn(address, uint256) external;
}

/// @title RaidBoss — Roguefall co-op raid against a daily rogue AI.
/// One shared boss with on-chain HP. Holders send their .ai agents (Roguefall NFTs, never escrowed) to attack;
/// each agent has a 1 hour cooldown. Damage = agent ATK x weapon bonus x a 75–125% roll, with a crit chance (x2).
/// When the boss falls:
///   - its RSHRD drop is split by damage share (claim() any time later),
///   - the wallet that landed the last hit gets 40% of the bounty pot in BNB, sent in the same tx
///     (credited for withdrawBounty() if the send fails),
///   - the next boss spawns at the next UTC day (00:00 UTC) with more HP (x1.15 growth + 40 HP per minted agent).
/// The bounty pot is this contract's BNB balance, filled by a fixed share of every paid mint.
/// No owner, no admin, no pause; nothing can take the pot except last hits.
contract RaidBoss is ReentrancyGuard {
    IRogueNFT public immutable nft;
    IShard public immutable shard;

    uint256 public constant COOLDOWN = 1 hours;
    uint256 public constant BASE_HP = 3000;
    uint256 public constant HP_PER_AGENT = 40;
    uint256 public constant GROWTH_PCT = 115;
    uint256 public constant BOUNTY_BPS = 4000;          // 40% of the pot to each last hit
    uint256 public constant REWARD_BASE = 10_000e18;     // boss #1 drop
    uint256 public constant REWARD_STEP = 1_000e18;      // +1,000 per boss
    uint256 public constant REWARD_MAX = 40_000e18;
    uint256 public constant UPGRADE_BASE = 300e18;       // weapon L -> L+1 burns 300 x (L+1)
    uint256 public constant MAX_WEAPON = 10;
    uint256 public constant WEAPON_PCT = 15;             // +15% damage per weapon level
    uint256 public constant MAX_BATCH = 25;

    struct Boss {
        uint64 maxHp;
        uint64 hp;
        uint40 spawnedAt;
        uint40 killedAt;
        address lastHitter;
        uint128 bounty;      // BNB paid to the last hitter
        uint128 reward;      // RSHRD dropped (split by damage share)
    }

    uint256 public bossNo;                  // current boss number (1-based)
    uint256 public growthHp;                // compounding part of max HP
    uint256 public nextSpawnDay;            // UTC day index when the next boss may spawn (when current is dead)
    mapping(uint256 => Boss) public bosses;
    mapping(uint256 => mapping(address => uint256)) public damageOn;     // boss => wallet => damage
    mapping(uint256 => mapping(address => bool)) public claimed;         // boss => wallet => shards claimed
    mapping(uint256 => address[10]) internal boards;                    // top 10 damage per boss

    mapping(uint256 => uint40) public lastAttack;   // agent id => timestamp
    mapping(uint256 => uint8) public weaponOf;      // agent id => weapon level
    mapping(uint256 => uint256) public damageByAgent;
    mapping(address => uint256) public totalDamage; // wallet lifetime
    mapping(address => uint256) public lastHits;    // wallet lifetime kills
    mapping(address => uint256) public owedBounty;  // only if a direct send failed
    uint256 public owedTotal;

    uint256 public totalAttacks;
    uint256 public totalBountyPaid;
    uint256 public totalShardsClaimed;

    event Funded(address indexed from, uint256 amount);
    event Spawned(uint256 indexed boss, uint256 maxHp, uint256 reward);
    event Hit(uint256 indexed boss, uint256 indexed id, address indexed who, uint256 damage, bool crit, uint256 hpLeft);
    event Killed(uint256 indexed boss, address indexed lastHitter, uint256 bounty, uint256 reward);
    event Claimed(address indexed who, uint256 indexed boss, uint256 shards);
    event Upgraded(uint256 indexed id, address indexed who, uint256 level, uint256 burned);

    constructor(address nft_, address shard_) {
        require(nft_ != address(0) && shard_ != address(0), "zero");
        nft = IRogueNFT(nft_); shard = IShard(shard_);
        growthHp = BASE_HP;
        _spawn(0); // the NFT is deployed right after this contract, so boss #1 starts with 0 minted agents
    }

    receive() external payable { emit Funded(msg.sender, msg.value); }

    // ------------------------------------------------------------------ views
    /// live bounty pot (excludes bounties already owed to past last hitters)
    function pot() public view returns (uint256) { return address(this).balance - owedTotal; }
    function nextBounty() external view returns (uint256) { return pot() * BOUNTY_BPS / 10000; }
    function alive() public view returns (bool) { return bosses[bossNo].hp > 0; }
    function nextSpawnAt() external view returns (uint256) { return alive() ? 0 : nextSpawnDay * 1 days; }
    function readyAt(uint256 id) public view returns (uint256) { uint256 t = lastAttack[id]; return t == 0 ? 0 : t + COOLDOWN; }
    function upgradeCost(uint256 id) public view returns (uint256) { return UPGRADE_BASE * (uint256(weaponOf[id]) + 1); }

    /// damage range before crit for an agent: [min, max]
    function damageRange(uint256 id) public view returns (uint256 lo, uint256 hi, uint256 critPct) {
        (uint256 atk, uint256 crit) = nft.statsOf(id);
        uint256 b = atk * (100 + WEAPON_PCT * weaponOf[id]) / 100;
        return (b * 75 / 100, b * 124 / 100, crit);
    }

    function top(uint256 boss) external view returns (address[10] memory who, uint256[10] memory dmg) {
        who = boards[boss];
        for (uint256 i; i < 10; ++i) if (who[i] != address(0)) dmg[i] = damageOn[boss][who[i]];
    }

    function pendingShards(address who, uint256 boss) public view returns (uint256) {
        Boss storage b = bosses[boss];
        if (b.killedAt == 0 || claimed[boss][who]) return 0;
        return uint256(b.reward) * damageOn[boss][who] / b.maxHp;
    }

    /// one-call snapshot for the site
    function state() external view returns (uint256 no, uint256 hp, uint256 maxHp, bool isAlive, uint256 spawnedAt, uint256 spawnAt,
        uint256 potBnb, uint256 reward, address lastKiller, uint256 attacks) {
        Boss storage b = bosses[bossNo];
        no = bossNo; hp = b.hp; maxHp = b.maxHp; isAlive = b.hp > 0; spawnedAt = b.spawnedAt;
        spawnAt = isAlive ? 0 : nextSpawnDay * 1 days; potBnb = pot(); reward = b.reward;
        lastKiller = bossNo > 1 && isAlive ? bosses[bossNo - 1].lastHitter : b.lastHitter;
        attacks = totalAttacks;
    }

    // ------------------------------------------------------------------ actions
    /// spawn the next boss once its UTC day has started (attack() does this automatically)
    function spawn() public {
        require(!alive() && block.timestamp / 1 days >= nextSpawnDay, "not yet");
        growthHp = growthHp * GROWTH_PCT / 100;
        _spawn(nft.totalSupply());
    }

    function attack(uint256[] calldata ids) external nonReentrant {
        require(msg.sender == tx.origin, "eoa only");
        require(ids.length > 0 && ids.length <= MAX_BATCH, "batch");
        if (!alive()) spawn();
        uint256 no = bossNo;
        Boss storage b = bosses[no];
        uint256 hp = b.hp;
        uint256 dealt;
        bytes32 seed = keccak256(abi.encodePacked(blockhash(block.number - 1), block.prevrandao, msg.sender, totalAttacks));
        for (uint256 i; i < ids.length && hp > 0; ++i) {
            uint256 id = ids[i];
            require(nft.ownerOf(id) == msg.sender, "not yours");
            require(block.timestamp >= readyAt(id), "cooling down");
            lastAttack[id] = uint40(block.timestamp);
            (uint256 lo, uint256 hi, uint256 critPct) = damageRange(id);
            uint256 r = uint256(keccak256(abi.encodePacked(seed, id, i)));
            uint256 d = lo + (r % (hi - lo + 1));
            bool crit = (r >> 128) % 100 < critPct;
            if (crit) d *= 2;
            if (d == 0) d = 1;
            if (d > hp) d = hp;
            hp -= d; dealt += d;
            damageByAgent[id] += d;
            emit Hit(no, id, msg.sender, d, crit, hp);
        }
        totalAttacks += 1;
        b.hp = uint64(hp);
        damageOn[no][msg.sender] += dealt;
        totalDamage[msg.sender] += dealt;
        _board(no, msg.sender);
        if (hp == 0) _kill(no, b);
    }

    function claim(uint256[] calldata bossIds) external nonReentrant returns (uint256 total) {
        for (uint256 i; i < bossIds.length; ++i) {
            uint256 amt = pendingShards(msg.sender, bossIds[i]);
            if (amt == 0) continue;
            claimed[bossIds[i]][msg.sender] = true;
            total += amt;
            emit Claimed(msg.sender, bossIds[i], amt);
        }
        require(total > 0, "nothing");
        totalShardsClaimed += total;
        shard.mint(msg.sender, total);
    }

    function upgrade(uint256 id) external nonReentrant {
        require(nft.ownerOf(id) == msg.sender, "not yours");
        uint256 lvl = weaponOf[id];
        require(lvl < MAX_WEAPON, "max");
        uint256 cost = UPGRADE_BASE * (lvl + 1);
        shard.raidBurn(msg.sender, cost);
        weaponOf[id] = uint8(lvl + 1);
        emit Upgraded(id, msg.sender, lvl + 1, cost);
    }

    function withdrawBounty() external nonReentrant {
        uint256 a = owedBounty[msg.sender];
        require(a > 0, "nothing");
        owedBounty[msg.sender] = 0;
        owedTotal -= a;
        (bool ok, ) = msg.sender.call{value: a}("");
        require(ok, "send failed");
    }

    // ------------------------------------------------------------------ internal
    function _spawn(uint256 minted) internal {
        uint256 no = ++bossNo;
        uint256 mh = growthHp + minted * HP_PER_AGENT;
        uint256 rw = REWARD_BASE + REWARD_STEP * (no - 1);
        if (rw > REWARD_MAX) rw = REWARD_MAX;
        bosses[no] = Boss(uint64(mh), uint64(mh), uint40(block.timestamp), 0, address(0), 0, uint128(rw));
        emit Spawned(no, mh, rw);
    }

    function _kill(uint256 no, Boss storage b) internal {
        uint256 bounty = pot() * BOUNTY_BPS / 10000;
        b.killedAt = uint40(block.timestamp);
        b.lastHitter = msg.sender;
        b.bounty = uint128(bounty);
        lastHits[msg.sender] += 1;
        nextSpawnDay = block.timestamp / 1 days + 1;
        totalBountyPaid += bounty;
        emit Killed(no, msg.sender, bounty, b.reward);
        if (bounty > 0) {
            (bool ok, ) = msg.sender.call{value: bounty}("");
            if (!ok) { owedBounty[msg.sender] += bounty; owedTotal += bounty; }
        }
    }

    function _board(uint256 no, address who) internal {
        address[10] storage bd = boards[no];
        uint256 e = damageOn[no][who];
        uint256 pos = 10;
        for (uint256 i; i < 10; ++i) if (bd[i] == who) { pos = i; break; }
        if (pos == 10) {
            if (bd[9] != address(0) && damageOn[no][bd[9]] >= e) return;
            pos = 9;
            bd[9] = who;
        }
        while (pos > 0 && (bd[pos - 1] == address(0) || damageOn[no][bd[pos - 1]] < e)) {
            (bd[pos - 1], bd[pos]) = (bd[pos], bd[pos - 1]);
            pos--;
        }
    }
}

