// ==== src/Heartbeat.sol ====
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@oz/utils/ReentrancyGuard.sol";

interface IKeepNFT {
    function ownerOf(uint256) external view returns (address);
    function statsOf(uint256) external view returns (uint256 power, uint256 extra);
}

interface IBeat {
    function mint(address, uint256) external;
    function gameBurn(address, uint256) external;
}

/// @title Heartbeat — PULSEKEEP keep-alive game on BNB Chain.
/// One shared heartbeat with a 10-minute countdown. Pinging with your .ai keeper agents (never escrowed)
/// resets the countdown and mints BEAT right away. Each agent can ping once per 30 minutes.
/// Combo: every ping tx from a DIFFERENT wallet than the previous keeper adds +1 combo (+5% BEAT, max +300%).
/// Flatline: when the countdown runs out (or 6 h after the beat started, whichever is first) the last keeper
/// wins 50% of the BNB keeper pot. settle() (or the next ping) pays it; if the send fails it is credited.
/// The pot is this contract's BNB balance, filled by a fixed share of every paid mint.
/// No owner, no admin, no pause; the pot only leaves through flatline payouts.
contract Heartbeat is ReentrancyGuard {
    IKeepNFT public immutable nft;
    IBeat public immutable token;

    uint256 public constant WINDOW = 10 minutes;
    uint256 public constant MAX_BEAT = 6 hours;
    uint256 public constant COOLDOWN = 30 minutes;
    uint256 public constant KEEPER_BPS = 5000;          // 50% of the pot to the last keeper
    uint256 public constant BASE_REWARD = 20e18;        // BEAT per ping at power 50, before combo/tune
    uint256 public constant HALVING_PINGS = 40_000;     // base halves every 40k agent pings (floor 1/16)
    uint256 public constant COMBO_PCT = 5;
    uint256 public constant MAX_COMBO = 60;
    uint256 public constant TUNE_BASE = 200e18;         // tune L -> L+1 burns 200 x (L+1) BEAT
    uint256 public constant MAX_TUNE = 10;
    uint256 public constant TUNE_PCT = 10;
    uint256 public constant MAX_BATCH = 25;

    struct Beat {
        uint40 start;
        uint40 end;
        address keeper;
        uint128 paid;
        uint32 pings;
        uint32 maxCombo;
    }

    uint256 public beatNo = 1;
    uint256 public deadline;
    address public lastKeeper;
    uint256 public combo;
    mapping(uint256 => Beat) public beats;
    mapping(uint256 => uint40) public lastPing;
    mapping(uint256 => uint8) public tuneOf;
    mapping(uint256 => uint256) public pingsByAgent;
    mapping(address => uint256) public keeperWins;
    mapping(address => uint256) public beatEarned;
    mapping(address => uint256) public owed;
    uint256 public owedTotal;
    uint256 public totalPings;
    uint256 public totalPaid;

    event Funded(address indexed from, uint256 amount);
    event Ping(uint256 indexed beat, address indexed who, uint256 agents, uint256 combo, uint256 minted, uint256 deadline);
    event Flatline(uint256 indexed beat, address indexed keeper, uint256 paid, uint256 pings, uint256 maxCombo);
    event Tuned(uint256 indexed id, address indexed who, uint256 level, uint256 burned);

    constructor(address nft_, address token_) {
        require(nft_ != address(0) && token_ != address(0), "zero");
        nft = IKeepNFT(nft_); token = IBeat(token_);
    }

    receive() external payable { emit Funded(msg.sender, msg.value); }

    // ------------------------------------------------------------------ views
    function pot() public view returns (uint256) { return address(this).balance - owedTotal; }
    function prize() public view returns (uint256) { return pot() * KEEPER_BPS / 10000; }
    function alive() public view returns (bool) { return lastKeeper != address(0) && block.timestamp <= deadline; }
    function flatlined() public view returns (bool) { return lastKeeper != address(0) && block.timestamp > deadline; }
    function readyAt(uint256 id) public view returns (uint256) { uint256 t = lastPing[id]; return t == 0 ? 0 : t + COOLDOWN; }
    function tuneCost(uint256 id) public view returns (uint256) { return TUNE_BASE * (uint256(tuneOf[id]) + 1); }
    function base() public view returns (uint256) { uint256 h = totalPings / HALVING_PINGS; return BASE_REWARD >> (h > 4 ? 4 : h); }

    /// combo the caller would get on a ping now
    function comboFor(address who) public view returns (uint256 c) {
        c = flatlined() || lastKeeper == address(0) ? 0 : combo;
        if (who != lastKeeper || flatlined()) c += 1;
        if (c > MAX_COMBO) c = MAX_COMBO;
    }

    function rewardOf(uint256 id, uint256 c) public view returns (uint256) {
        (uint256 p, ) = nft.statsOf(id);
        if (c > MAX_COMBO) c = MAX_COMBO;
        return base() * p / 50 * (100 + TUNE_PCT * tuneOf[id]) / 100 * (100 + COMBO_PCT * c) / 100;
    }

    function state() external view returns (uint256 no, bool isAlive, uint256 dl, address keeper, uint256 c, uint256 potBnb,
        uint256 prizeBnb, uint256 start, uint256 pings, uint256 baseReward, address lastWinner, uint256 lastPaid) {
        no = beatNo; isAlive = alive(); dl = deadline; keeper = lastKeeper; c = combo; potBnb = pot(); prizeBnb = prize();
        start = beats[beatNo].start; pings = beats[beatNo].pings; baseReward = base();
        if (beatNo > 1) { lastWinner = beats[beatNo - 1].keeper; lastPaid = beats[beatNo - 1].paid; }
    }

    // ------------------------------------------------------------------ actions
    function settle() public nonReentrant { _settleIfDue(); }

    function ping(uint256[] calldata ids) external nonReentrant {
        require(msg.sender == tx.origin, "eoa only");
        require(ids.length > 0 && ids.length <= MAX_BATCH, "batch");
        _settleIfDue();
        Beat storage B = beats[beatNo];
        if (lastKeeper == address(0)) { B.start = uint40(block.timestamp); combo = 0; }
        if (msg.sender != lastKeeper) combo += 1;
        uint256 c = combo > MAX_COMBO ? MAX_COMBO : combo;
        uint256 minted;
        for (uint256 i; i < ids.length; ++i) {
            uint256 id = ids[i];
            require(nft.ownerOf(id) == msg.sender, "not yours");
            require(block.timestamp >= readyAt(id), "cooling down");
            lastPing[id] = uint40(block.timestamp);
            minted += rewardOf(id, c);
            pingsByAgent[id] += 1;
        }
        totalPings += ids.length;
        B.pings += uint32(ids.length);
        if (combo > B.maxCombo) B.maxCombo = uint32(combo);
        uint256 dl = block.timestamp + WINDOW;
        uint256 hard = uint256(B.start) + MAX_BEAT;
        deadline = dl < hard ? dl : hard;
        lastKeeper = msg.sender;
        beatEarned[msg.sender] += minted;
        emit Ping(beatNo, msg.sender, ids.length, combo, minted, deadline);
        token.mint(msg.sender, minted);
    }

    function tune(uint256 id) external nonReentrant {
        require(nft.ownerOf(id) == msg.sender, "not yours");
        uint256 lvl = tuneOf[id];
        require(lvl < MAX_TUNE, "max");
        uint256 cost = TUNE_BASE * (lvl + 1);
        token.gameBurn(msg.sender, cost);
        tuneOf[id] = uint8(lvl + 1);
        emit Tuned(id, msg.sender, lvl + 1, cost);
    }

    function withdrawOwed() external nonReentrant {
        uint256 a = owed[msg.sender];
        require(a > 0, "nothing");
        owed[msg.sender] = 0; owedTotal -= a;
        (bool ok, ) = msg.sender.call{value: a}("");
        require(ok, "send failed");
    }

    // ------------------------------------------------------------------ internal
    function _settleIfDue() internal {
        if (!flatlined()) return;
        address k = lastKeeper;
        uint256 p = prize();
        Beat storage B = beats[beatNo];
        B.end = uint40(deadline); B.keeper = k; B.paid = uint128(p);
        keeperWins[k] += 1; totalPaid += p;
        emit Flatline(beatNo, k, p, B.pings, B.maxCombo);
        beatNo += 1; lastKeeper = address(0); combo = 0; deadline = 0;
        if (p > 0) {
            (bool ok, ) = k.call{value: p, gas: 50000}("");
            if (!ok) { owed[k] += p; owedTotal += p; }
        }
    }
}

