// ==== PixelApes.sol ====
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/Base64.sol";

contract PixelApes is ERC721, Ownable {
    using Strings for uint256;
    uint256 public immutable MAX_SUPPLY;
    uint256 public constant MAX_PER_WALLET = 2;
    uint256 public mintPrice;
    address payable public payoutWallet;
    uint256 public totalMinted;
    mapping(address => uint256) public mintedPerWallet;

    constructor(uint256 _maxSupply, uint256 _mintPrice, address payable _owner) ERC721("PIXEL APES", "APES") Ownable(_owner) {
        MAX_SUPPLY = _maxSupply;
        mintPrice = _mintPrice;
        payoutWallet = _owner;
    }

    function setMintPrice(uint256 _price) external onlyOwner { mintPrice = _price; }
    function setPayoutWallet(address payable _w) external onlyOwner { payoutWallet = _w; }

    function mint() external payable {
        require(totalMinted < MAX_SUPPLY, "Sold out");
        uint256 count = mintedPerWallet[msg.sender];
        require(count < MAX_PER_WALLET, "Wallet limit");
        if (count == 0) {
            require(msg.value == mintPrice, "First mint costs mintPrice");
            (bool ok, ) = payoutWallet.call{value: msg.value}("");
            require(ok, "Payout failed");
        } else {
            require(msg.value == 0, "Second mint free");
        }
        mintedPerWallet[msg.sender] = count + 1;
        totalMinted += 1;
        _safeMint(msg.sender, totalMinted);
    }

    function _fur(uint256 seed) internal pure returns (string memory) {
        uint256 r = seed % 5;
        if (r == 0) return "#8d6e63";
        if (r == 1) return "#6d4c41";
        if (r == 2) return "#a1887f";
        if (r == 3) return "#5d4037";
        return "#bcaaa4";
    }
    function _bg(uint256 seed) internal pure returns (string memory) {
        uint256 r = (seed / 5) % 5;
        if (r == 0) return "#111827";
        if (r == 1) return "#1e3a8a";
        if (r == 2) return "#831843";
        if (r == 3) return "#064e3b";
        return "#422006";
    }
    function _accessory(uint256 seed) internal pure returns (string memory) {
        uint256 r = (seed / 25) % 4;
        if (r == 0) return '<rect x="60" y="30" width="80" height="18" fill="#dc2626"/>';
        if (r == 1) return '<rect x="55" y="75" width="90" height="20" fill="#111827" opacity="0.85"/>';
        if (r == 2) return '<circle cx="100" cy="35" r="10" fill="#facc15"/>';
        return "";
    }

    function _svg(uint256 tokenId) internal view returns (string memory) {
        uint256 seed = uint256(keccak256(abi.encodePacked(tokenId))) % 1000;
        string memory fur = _fur(seed);
        return string(abi.encodePacked(
            '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 200 200" shape-rendering="crispEdges"><rect width="200" height="200" fill="', _bg(seed), '"/>',
            '<rect x="30" y="60" width="40" height="50" fill="', fur, '"/><rect x="130" y="60" width="40" height="50" fill="', fur, '"/>',
            '<rect x="50" y="40" width="100" height="110" rx="20" fill="', fur, '"/>',
            '<rect x="65" y="95" width="70" height="40" rx="12" fill="#d7ccc8"/>',
            '<rect x="75" y="75" width="15" height="15" fill="#111827"/><rect x="110" y="75" width="15" height="15" fill="#111827"/>',
            '<rect x="90" y="105" width="20" height="8" fill="#111827"/><rect x="85" y="125" width="30" height="6" fill="#111827"/>',
            _accessory(seed),
            '<text x="100" y="190" font-family="sans-serif" font-size="12" fill="#ffffff" text-anchor="middle">PIXEL APES #', tokenId.toString(), '</text></svg>'
        ));
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(_ownerOf(tokenId) != address(0), "No token");
        string memory json = Base64.encode(bytes(string(abi.encodePacked(
            '{"name":"PIXEL APES #', tokenId.toString(), '","description":"PIXEL APES: 1,111 supply. First mint per wallet costs $0.8, second mint per wallet is free, max 2 per wallet.","attributes":[],"image":"data:image/svg+xml;base64,',
            Base64.encode(bytes(_svg(tokenId))), '"}'
        ))));
        return string(abi.encodePacked("data:application/json;base64,", json));
    }

    function withdraw() external onlyOwner {
        (bool ok, ) = payoutWallet.call{value: address(this).balance}("");
        require(ok, "Withdraw failed");
    }
}

