pragma solidity 0.8.34;

import {AccessControlEnumerable, AccessControl} from "@openzeppelin/contracts/access/AccessControlEnumerable.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {Pausable} from "@openzeppelin/contracts/security/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IVaultContract} from "./interfaces/IVaultContract.sol";

/**
 * @title IERC1271
 * @notice Interface for ERC-1271 smart contract wallet signature verification.
 */
interface IERC1271 {
    function isValidSignature(
        bytes32 hash,
        bytes memory signature
    ) external view returns (bytes4 magicValue);
}

/**
 * @title TokenContract
 * @notice ERC-20 token (18 decimals) representing underlying ERC-3643 assets, backed by collateral
 *         locked across a registry of vaults.
 * @dev Signature-gated mint/burn against a registry of vaults, with a capped transfer tax, blocklist,
 *      pausability, and timelocked role management. Behavior and invariants are documented on each
 *      function, state variable, and error.
 */
contract TokenContract is
    ERC20,
    AccessControlEnumerable,
    Pausable,
    ReentrancyGuard
{
    /// @notice Role identifier whose holders sign EIP-712 mint authorizations.
    /// @dev Granted to a constructor param, can be granted to others via timelocked grantRole.
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    /// @notice Role identifier whose holders sign EIP-712 burn authorizations.
    /// @dev Granted to a constructor param, can be granted to others via timelocked grantRole.
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");

    /// @notice Role identifier for pause/unpause functionality.
    /// @dev Granted to admin in constructor, can be granted to others via timelocked grantRole.
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Maximum allowed transfer tax rate in basis points (1% = 100 bps).
    /// @dev Hard cap to protect users from excessive transfer taxation.
    uint256 public constant MAX_TRANSFER_TAX_BPS = 100;

    /// @notice Basis points denominator (10000 = 100%).
    /// @dev Used for all basis point calculations.
    uint256 public constant BPS_DENOMINATOR = 10_000;

    /// @notice Maximum discount percentage in basis points (100% = 10000 bps).
    /// @dev Hard cap for discount tiers.
    uint256 public constant MAX_DISCOUNT_BPS = 10_000;

    /// @notice Timelock delay for role grants.
    /// @dev Provides time to detect and cancel malicious role grants.
    /// @custom:security Critical for preventing instant privilege escalation.
    uint256 public constant ROLE_GRANT_DELAY = 2 days;

    /// @notice EIP-712 typehash for mint signature verification.
    /// @dev Used to construct the digest for signature verification in mint().
    bytes32 public constant MINT_TYPEHASH =
        keccak256(
            "Mint(address to,uint256 amount,address vault,address erc3643Token,uint256 nonce,uint256 deadline)"
        );

    /// @notice EIP-712 typehash for plain burn signature verification.
    /// @dev Used to construct the digest for signature verification in burn().
    bytes32 public constant BURN_PLAIN_TYPEHASH =
        keccak256(
            "BurnPlain(address owner,uint256 amount,address vault,address erc3643Token,uint256 nonce,uint256 deadline)"
        );

    /// @notice EIP-712 typehash for atomic burn-and-redeem signature verification.
    /// @dev Used to construct the digest for signature verification in burnAndRedeem().
    bytes32 public constant BURN_REDEEM_TYPEHASH =
        keccak256(
            "BurnAndRedeem(address owner,uint256 amount,address vault,address erc3643Token,uint256 nonce,uint256 deadline)"
        );

    /// @notice EIP-1271 magic value returned on successful signature validation.
    bytes4 private constant EIP1271_MAGIC_VALUE = 0x1626ba7e;

    /// @notice Maximum allowed deadline drift from current block timestamp.
    /// @dev Prevents signatures with deadlines too far in the future.
    uint256 public constant MAX_DEADLINE_DRIFT = 10 minutes;

    /// @notice Bitmask for extracting discount basis points from packed tier data.
    /// @dev Used with _packedDiscountTiers to extract the lower 32 bits (discountBps).
    uint256 private constant _DISCOUNT_MASK = type(uint32).max;

    /// @notice Chain ID cached at deployment for EIP-712 domain separator.
    /// @dev Used to detect chain forks; if block.chainid differs, separator is recomputed.
    uint256 private immutable _cachedChainId;

    /// @notice EIP-712 domain separator cached at deployment.
    /// @dev Returned directly when block.chainid matches _cachedChainId; recomputed otherwise.
    bytes32 private immutable _cachedDomainSeparator;

    /// @notice Tracks which vaults are registered and may back mint/burn operations.
    /// @dev Managed by DEFAULT_ADMIN_ROLE via registerVault/deregisterVault.
    mapping(address vault => bool isRegistered) public registeredVaults;

    /// @notice ERC-20 token amount currently backed by each vault.
    /// @dev Incremented by amount on mint, decremented by amount on both burns. Gates deregistration.
    mapping(address vault => uint256 amount) public lockedByVault;

    /// @notice Transfer tax rate in basis points (max 100 = 1%).
    /// @dev Applied to transfers except: mints, burns, taxRecipient transfers, tax exempt addresses.
    uint256 public transferTaxBps;

    /// @notice ERC20 token used for transfer tax discounts (address(0) = disabled).
    /// @dev Users holding this token receive reduced transfer taxes based on tier thresholds.
    address public discountToken;

    /// @notice Address that receives collected transfer taxes.
    /// @dev Initialized in the constructor and updatable via setTaxRecipient(). Cannot be blocklisted.
    /// @custom:security Critical - all tax revenue flows to this address.
    address public taxRecipient;

    /// @dev pack: [ threshold | discountBps ]
    /// @dev use 32 bits for discountBps (more than enough for 0..10_000)
    uint256[3] private _packedDiscountTiers;

    /// @notice Mapping of addresses exempt from transfer tax.
    /// @dev Tax exempt addresses pay no transfer tax when sending OR receiving.
    mapping(address account => bool isExempt) public taxExemptAddresses;

    /// @notice Mapping of blocklisted addresses for ERC20 token transfers.
    /// @dev Blocklisted addresses cannot send or receive tokens.
    mapping(address account => bool isBlocklisted) public blocklisted;

    /// @notice Mapping of pending role grants to their executable timestamp.
    /// @dev Key is keccak256(abi.encode(role, account)). Value 0 means not queued.
    mapping(bytes32 grantKey => uint256 executableAt) public pendingRoleGrants;

    /// @notice Sequential per-wallet nonce for EIP-712 replay protection.
    /// @dev Keyed on the recipient (`to`) for mint and the owner for both burns; set to nonce + 1
    ///      after each successful use. A single shared sequence per wallet (mint + burn).
    mapping(address account => uint256 nonce) public nonces;

    /// @notice Emitted when a vault is registered.
    /// @param vault The address of the registered vault.
    event VaultRegistered(address indexed vault);

    /// @notice Emitted when a vault is deregistered.
    /// @param vault The address of the deregistered vault.
    event VaultDeregistered(address indexed vault);

    /// @notice Emitted when a stranded lockedByVault residue is administratively cleared.
    /// @param vault The vault whose locked-supply counter was reset to zero.
    /// @param previous The lockedByVault value that was cleared.
    event LockedByVaultReconciled(address indexed vault, uint256 previous);

    /// @notice Emitted when tokens are minted via EIP-712 signed authorization.
    /// @param to The address that received the minted tokens.
    /// @param amount The amount of tokens minted.
    /// @param vault The vault that locked the backing collateral.
    /// @param erc3643Token The ERC-3643 token locked in the vault to back these tokens.
    /// @param nonce The nonce used for this mint operation.
    event Minted(
        address indexed to,
        uint256 amount,
        address indexed vault,
        address indexed erc3643Token,
        uint256 nonce
    );

    /// @notice Emitted when tokens are burned via EIP-712 signed authorization.
    /// @param owner The address whose tokens were burned.
    /// @param amount The amount of tokens burned.
    /// @param vault The vault whose backing collateral reservation was released.
    /// @param erc3643Token The ERC-3643 token unlocked from the vault.
    /// @param nonce The nonce used for this burn operation.
    /// @param redeemed True when the underlying asset was delivered and frozen, false for a plain burn.
    event Burned(
        address indexed owner,
        uint256 amount,
        address indexed vault,
        address indexed erc3643Token,
        uint256 nonce,
        bool redeemed
    );

    /// @notice Emitted when an address is added to the blocklist.
    /// @param account The address that was blocklisted.
    event AddressBlocklisted(address indexed account);

    /// @notice Emitted when an address is removed from the blocklist.
    /// @param account The address that was unblocklisted.
    event AddressUnblocklisted(address indexed account);

    /// @notice Emitted when transfer tax rate is updated.
    /// @param oldTaxBps The previous tax rate in basis points.
    /// @param newTaxBps The new tax rate in basis points.
    event TransferTaxUpdated(
        uint256 indexed oldTaxBps,
        uint256 indexed newTaxBps
    );

    /// @notice Emitted when tax recipient address is updated.
    /// @param oldRecipient The previous tax recipient address.
    /// @param newRecipient The new tax recipient address.
    event TaxRecipientUpdated(
        address indexed oldRecipient,
        address indexed newRecipient
    );

    /// @notice Emitted when transfer tax is collected.
    /// @param from The sender of the transfer.
    /// @param to The intended recipient of the transfer.
    /// @param taxAmount The amount of tax collected.
    event TransferTaxCollected(
        address indexed from,
        address indexed to,
        uint256 taxAmount
    );

    /// @notice Emitted when a role grant is queued.
    /// @param role The role being granted.
    /// @param account The account receiving the role.
    /// @param executableAt The timestamp when the grant can be executed.
    event RoleGrantQueued(
        bytes32 indexed role,
        address indexed account,
        uint256 executableAt
    );

    /// @notice Emitted when a role grant is executed.
    /// @param role The role that was granted.
    /// @param account The account that received the role.
    event RoleGrantExecuted(bytes32 indexed role, address indexed account);

    /// @notice Emitted when a role grant is cancelled.
    /// @param role The role that was cancelled.
    /// @param account The account that was supposed to receive the role.
    event RoleGrantCancelled(bytes32 indexed role, address indexed account);

    /// @notice Emitted when discount token is updated.
    /// @param oldToken The previous discount token address.
    /// @param newToken The new discount token address.
    event DiscountTokenUpdated(
        address indexed oldToken,
        address indexed newToken
    );

    /// @notice Emitted when discount tiers are updated.
    /// @param thresholds Array of 3 tier thresholds.
    /// @param discountBps Array of 3 discount percentages in basis points.
    event DiscountTiersUpdated(uint256[3] thresholds, uint256[3] discountBps);

    /// @notice Emitted when an address is added to tax exemption list.
    /// @param account The address that was added.
    event TaxExemptAdded(address indexed account);

    /// @notice Emitted when an address is removed from tax exemption list.
    /// @param account The address that was removed.
    event TaxExemptRemoved(address indexed account);

    /// @notice Emitted when transfer tax discount is applied.
    /// @param from The sender who received the discount.
    /// @param to The recipient of the transfer.
    /// @param originalTax The tax amount before discount.
    /// @param discountedTax The tax amount after discount.
    /// @param discountBps The discount percentage applied.
    event TransferTaxDiscountApplied(
        address indexed from,
        address indexed to,
        uint256 originalTax,
        uint256 discountedTax,
        uint256 discountBps
    );

    /// @notice Emitted when tokens are rescued from the contract.
    /// @param token The address of the rescued token.
    /// @param to The address that received the rescued tokens.
    /// @param amount The amount of tokens rescued.
    event TokensRescued(
        address indexed token,
        address indexed to,
        uint256 amount
    );

    /// @notice Thrown when an address parameter is the zero address.
    error ZeroAddressNotAllowed();

    /// @notice Thrown when address has no code (not a contract).
    /// @param account The EOA address that was expected to be a contract.
    error NotAContract(address account);

    /// @notice Thrown when an amount parameter is zero.
    error ZeroAmountNotAllowed();

    /// @notice Thrown when a mint or burn names a vault that is not registered.
    /// @param vault The vault that is not registered.
    error VaultNotRegistered(address vault);

    /// @notice Thrown when registering a vault that is already registered.
    /// @param vault The vault that is already registered.
    error VaultAlreadyRegistered(address vault);

    /// @notice Thrown when deregistering a vault that still backs circulating supply.
    /// @param vault The vault that still backs supply.
    /// @param amount The ERC-20 token amount still backed by the vault.
    error VaultHasLockedSupply(address vault, uint256 amount);

    /// @notice Thrown when deregistering or reconciling a vault that still holds locked collateral.
    /// @param vault The vault that still holds underlying collateral.
    error VaultHasLockedCollateral(address vault);

    /// @notice Thrown when reconciling a vault whose lockedByVault counter is already zero.
    /// @param vault The vault with no residue to reconcile.
    error NoResidueToReconcile(address vault);

    /// @notice Thrown when registering a vault whose bound tokenContract is not this contract.
    /// @param vault The vault being registered.
    /// @param boundTokenContract The tokenContract the vault reports as its authority.
    error VaultTokenContractMismatch(address vault, address boundTokenContract);

    /// @notice Thrown when the signature deadline has passed.
    error SignatureExpired();

    /// @notice Thrown when the signature deadline is too far in the future.
    /// @param deadline The provided deadline timestamp.
    /// @param maxAllowed The maximum allowed deadline (block.timestamp + MAX_DEADLINE_DRIFT).
    error DeadlineTooFarInFuture(uint256 deadline, uint256 maxAllowed);

    /// @notice Thrown when signature verification fails (not from a holder of the required role).
    error InvalidSignature();

    /// @notice Thrown when the provided nonce does not match the wallet's expected nonce.
    /// @param provided The nonce supplied in the call.
    /// @param expected The wallet's current expected nonce (nonces[to] for mint, nonces[owner] for burn).
    error InvalidNonce(uint256 provided, uint256 expected);

    /// @notice Thrown when burn is attempted without sufficient allowance from the token owner.
    /// @param owner The token owner whose allowance is insufficient.
    /// @param required The amount required to burn.
    /// @param available The current allowance granted to this contract.
    error InsufficientAllowance(
        address owner,
        uint256 required,
        uint256 available
    );

    /// @notice Thrown when the vault's unlock call returns false during a plain burn.
    /// @param vault The vault whose unlock call failed.
    /// @param erc3643Token The ERC-3643 token that failed to unlock.
    /// @param amount The ERC-20 amount whose backing reservation failed to release.
    error VaultUnlockFailed(
        address vault,
        address erc3643Token,
        uint256 amount
    );

    /// @notice Thrown when the vault's unlockAndFreeze call returns false during a burn-and-redeem.
    /// @param vault The vault whose unlockAndFreeze call failed.
    /// @param erc3643Token The ERC-3643 token that failed to unlock and freeze.
    /// @param amount The ERC-20 amount whose redemption failed.
    /// @param owner The address that was to receive the frozen underlying asset.
    error VaultUnlockAndFreezeFailed(
        address vault,
        address erc3643Token,
        uint256 amount,
        address owner
    );

    /// @notice Thrown when address is blocklisted and attempts transfer.
    /// @param account The blocklisted address.
    error AddressIsBlocklisted(address account);

    /// @notice Thrown when address is already blocklisted.
    /// @param account The already blocklisted address.
    error AddressAlreadyBlocklisted(address account);

    /// @notice Thrown when address is not blocklisted.
    /// @param account The address that is not blocklisted.
    error AddressNotBlocklisted(address account);

    /// @notice Thrown when attempting to blocklist the tax recipient.
    error CannotBlocklistTaxRecipient();

    /// @notice Thrown when tax rate exceeds maximum allowed.
    /// @param provided The tax rate that was provided.
    /// @param maximum The maximum allowed (MAX_TRANSFER_TAX_BPS).
    error TaxRateExceedsMaximum(uint256 provided, uint256 maximum);

    /// @notice Thrown when a discount exceeds its effective maximum. Reused for two cases:
    ///         an active tier whose discount exceeds MAX_DISCOUNT_BPS, and a disabled tier
    ///         (threshold == 0) that carries a non-zero discount.
    /// @param provided The discount that was provided.
    /// @param maximum The effective maximum allowed: MAX_DISCOUNT_BPS for an active tier, or 0
    ///        for a disabled (zero-threshold) tier, which must carry no discount.
    error DiscountExceedsMaximum(uint256 provided, uint256 maximum);

    /// @notice Thrown when discount tiers are not in ascending order.
    error DiscountTiersNotAscending();

    /// @notice Thrown when non-contiguous discount tiers are provided (zero tier between active tiers).
    error NonContiguousTiersNotAllowed();

    /// @notice Thrown when discount tier threshold exceeds maximum that can be packed (uint224).
    error ThresholdExceedsMaximum();

    /// @notice Thrown when address is already tax exempt.
    /// @param account The already tax exempt address.
    error AddressAlreadyTaxExempt(address account);

    /// @notice Thrown when address is not tax exempt.
    /// @param account The address that is not tax exempt.
    error AddressNotTaxExempt(address account);

    /// @notice Thrown when attempting to execute or cancel a non-existent role grant.
    error RoleGrantNotQueued();

    /// @notice Thrown when attempting to execute a role grant before delay has passed.
    /// @param executableAt The timestamp when the grant becomes executable.
    /// @param currentTime The current block timestamp.
    error RoleGrantNotReady(uint256 executableAt, uint256 currentTime);

    /// @notice Thrown when attempting to queue a role grant that is already pending.
    error RoleGrantAlreadyQueued();

    /// @notice Thrown when attempting to grant a role to an account that already has it.
    error AccountAlreadyHasRole();

    /// @notice Thrown when the last admin tries to renounce their role.
    /// @dev Ensures the contract always has at least one admin.
    error CannotRenounceLastAdmin();

    /// @notice Thrown when attempting to revoke the last admin's role.
    /// @dev Ensures the contract always has at least one admin.
    error CannotRevokeLastAdmin();

    /**
     * @notice Creates a new TokenContract.
     * @param _name The name of the ERC20 token.
     * @param _symbol The symbol of the ERC20 token.
     * @param _admin The address granted DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
     * @param _minter The address granted MINTER_ROLE (signs mint authorizations).
     * @param _burner The address granted BURNER_ROLE (signs burn authorizations).
     * @param _taxRecipient The address that will receive collected taxes.
     * @dev Initialization notes:
     *      - Roles are granted directly without timelock (the only exception to the timelock rule)
     *      - Tax rates start at 0 and must be configured separately
     *      - MINTER_ROLE and BURNER_ROLE are the signer roles for mint and burn EIP-712 signatures
     *      - EIP-712 domain separator is cached using the token name and version "1"
     *
     * @custom:security Constructor is the only place where roles are granted without timelock.
     */
    constructor(
        string memory _name,
        string memory _symbol,
        address _admin,
        address _minter,
        address _burner,
        address _taxRecipient
    ) ERC20(_name, _symbol) {
        if (_admin == address(0)) revert ZeroAddressNotAllowed();
        if (_minter == address(0)) revert ZeroAddressNotAllowed();
        if (_burner == address(0)) revert ZeroAddressNotAllowed();
        if (_taxRecipient == address(0)) revert ZeroAddressNotAllowed();

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(PAUSER_ROLE, _admin);
        _grantRole(MINTER_ROLE, _minter);
        _grantRole(BURNER_ROLE, _burner);
        taxRecipient = _taxRecipient;

        _cachedChainId = block.chainid;
        _cachedDomainSeparator = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256(bytes(_name)),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );

        emit TaxRecipientUpdated(address(0), _taxRecipient);
    }

    /**
     * @notice Returns the EIP-712 domain separator.
     * @dev Returns the cached value when on the original chain; recomputes on chain fork.
     *      This ensures signatures are invalid on forked chains, preventing cross-chain replay attacks.
     * @return The EIP-712 domain separator for the current chain.
     */
    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return _domainSeparator();
    }

    /**
     * @dev Computes or returns the cached EIP-712 domain separator.
     *      If block.chainid matches the deployment chain, returns the cached value.
     *      Otherwise, recomputes to ensure correct chain binding on forks.
     */
    function _domainSeparator() internal view returns (bytes32) {
        if (block.chainid == _cachedChainId) {
            return _cachedDomainSeparator;
        }
        return
            keccak256(
                abi.encode(
                    keccak256(
                        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                    ),
                    keccak256(bytes(name())),
                    keccak256(bytes("1")),
                    block.chainid,
                    address(this)
                )
            );
    }

    /**
     * @notice Registers a vault so it can back mint and burn operations.
     * @param vault The vault contract to register.
     * @dev Only callable by DEFAULT_ADMIN_ROLE. The vault must be a non-zero contract address whose
     *      immutable tokenContract() points back at this contract, enforcing the reverse half of the
     *      vault <-> token binding. A non-conforming vault (no tokenContract() getter) reverts on the
     *      external call, which is an acceptable rejection. The check is registration-only;
     *      deregisterVault and reconcileLockedByVault are unaffected so removal/re-registration works.
     */
    function registerVault(
        address vault
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (vault == address(0)) revert ZeroAddressNotAllowed();
        if (vault.code.length == 0) revert NotAContract(vault);
        address boundTokenContract = IVaultContract(vault).tokenContract();
        if (boundTokenContract != address(this))
            revert VaultTokenContractMismatch(vault, boundTokenContract);
        if (registeredVaults[vault]) revert VaultAlreadyRegistered(vault);

        registeredVaults[vault] = true;

        emit VaultRegistered(vault);
    }

    /**
     * @notice Deregisters a vault from the registry.
     * @param vault The vault contract to deregister.
     * @dev Only callable by DEFAULT_ADMIN_ROLE. Reverts unless the vault is registered and
     *      no longer backs any circulating supply (lockedByVault[vault] == 0).
     * @dev lockedByVault[vault] is operator-maintained; the removal-safety guard holds only if each
     *      burn names the vault its tokens were minted against. See docs/new_token_flow.md.
     */
    function deregisterVault(
        address vault
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!registeredVaults[vault]) revert VaultNotRegistered(vault);

        uint256 locked = lockedByVault[vault];
        if (locked != 0) revert VaultHasLockedSupply(vault, locked);

        if (IVaultContract(vault).hasAnyLocked())
            revert VaultHasLockedCollateral(vault);

        delete registeredVaults[vault];

        emit VaultDeregistered(vault);
    }

    /**
     * @notice Clears a stranded lockedByVault residue for a vault that holds no underlying collateral.
     * @param vault The registered vault whose share-side counter has desynced.
     * @dev Only callable by DEFAULT_ADMIN_ROLE. Resets lockedByVault[vault] to zero ONLY when the
     *      vault reports no locked underlying collateral (hasAnyLocked() == false), so the reset can
     *      never mask real backing. This enables deregistration of a vault whose share-side counter
     *      desynced from the collateral side (for example a sub-minimum residue left by the unlock
     *      cap, or a burn that named the wrong token). Reverts if the vault is not registered, if it
     *      still holds collateral, or if there is no residue to reconcile.
     */
    function reconcileLockedByVault(
        address vault
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!registeredVaults[vault]) revert VaultNotRegistered(vault);
        if (IVaultContract(vault).hasAnyLocked())
            revert VaultHasLockedCollateral(vault);

        uint256 previous = lockedByVault[vault];
        if (previous == 0) revert NoResidueToReconcile(vault);

        lockedByVault[vault] = 0;

        emit LockedByVaultReconciled(vault, previous);
    }

    /**
     * @notice Mints tokens to a recipient, backed by collateral locked in the named vault, under an
     *         EIP-712 signed authorization.
     * @param to The address to mint tokens to.
     * @param amount The amount of tokens to mint (18 decimals).
     * @param vault The registered vault that locks the backing collateral.
     * @param erc3643Token The ERC-3643 token to lock in the vault as backing.
     * @param nonce The recipient's expected nonce; must equal nonces[to].
     * @param deadline The deadline timestamp for the signature (must not be expired or too far in future).
     * @param signature The EIP-712 signature from a MINTER_ROLE holder authorizing this mint.
     * @dev Flow:
     *      1. Validates inputs (recipient, amount) and deadline bounds
     *      2. Requires the named vault to be registered
     *      3. Builds and verifies the EIP-712 digest against a MINTER_ROLE signer
     *      4. Consumes the recipient's nonce
     *      5. Locks backing in the vault, increments lockedByVault, mints ERC-20 tokens, emits Minted
     *
     * @custom:security
     *      - Nonce is consumed BEFORE external calls (CEI pattern)
     *      - Signature cannot be replayed due to the per-wallet nonce
     *      - Deadline prevents stale signatures from being used
     *      - vault.lock() applies the vault's conversion rules and reverts if insufficient
     *        unlocked balance exists
     */
    function mint(
        address to,
        uint256 amount,
        address vault,
        address erc3643Token,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) external whenNotPaused nonReentrant {
        if (to == address(0)) revert ZeroAddressNotAllowed();
        if (amount == 0) revert ZeroAmountNotAllowed();
        if (blocklisted[msg.sender]) revert AddressIsBlocklisted(msg.sender);
        _checkDeadline(deadline);
        if (!registeredVaults[vault]) revert VaultNotRegistered(vault);

        bytes32 structHash = keccak256(
            abi.encode(
                MINT_TYPEHASH,
                to,
                amount,
                vault,
                erc3643Token,
                nonce,
                deadline
            )
        );
        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", _domainSeparator(), structHash)
        );

        (bool isValid, ) = _isValidSignature(digest, signature, MINTER_ROLE);
        if (!isValid) revert InvalidSignature();

        if (nonce != nonces[to]) revert InvalidNonce(nonce, nonces[to]);
        nonces[to] = nonce + 1;

        IVaultContract(vault).lock(erc3643Token, amount);
        lockedByVault[vault] += amount;
        _mint(to, amount);

        emit Minted(to, amount, vault, erc3643Token, nonce);
    }

    /**
     * @notice Burns tokens from the owner's balance and releases the backing collateral reservation.
     * @param owner The address whose tokens will be burned.
     * @param amount The amount of tokens to burn (18 decimals).
     * @param vault The registered vault whose backing collateral reservation is released.
     * @param erc3643Token The ERC-3643 token to unlock in the vault.
     * @param nonce The owner's expected nonce; must equal nonces[owner].
     * @param deadline The deadline timestamp for the signature (must not be expired or too far in future).
     * @param signature The EIP-712 signature from a BURNER_ROLE holder authorizing this burn.
     * @dev Plain burn: destroys ERC-20 and frees the backing reservation. No asset is delivered.
     *      Flow:
     *      1. Validates parameters and deadline bounds
     *      2. Requires the named vault to be registered
     *      3. Verifies the owner has approved this contract for at least `amount`
     *      4. Builds and verifies the EIP-712 digest against a BURNER_ROLE signer and consumes the
     *         owner's nonce
     *      5. Spends allowance, burns the ERC-20, and calls vault.unlock()
     *      6. Decrements lockedByVault[vault]
     * @dev lockedByVault[vault] is operator-maintained; the removal-safety guard holds only if each
     *      burn names the vault its tokens were minted against. See docs/new_token_flow.md.
     */
    function burn(
        address owner,
        uint256 amount,
        address vault,
        address erc3643Token,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) external whenNotPaused nonReentrant {
        if (blocklisted[msg.sender]) revert AddressIsBlocklisted(msg.sender);

        uint256 currentNonce = _validateAndConsumeBurn(
            BURN_PLAIN_TYPEHASH,
            owner,
            amount,
            vault,
            erc3643Token,
            nonce,
            deadline,
            signature
        );

        _spendAllowance(owner, address(this), amount);
        _burn(owner, amount);

        if (!IVaultContract(vault).unlock(erc3643Token, amount)) {
            revert VaultUnlockFailed(vault, erc3643Token, amount);
        }
        lockedByVault[vault] -= amount;

        emit Burned(owner, amount, vault, erc3643Token, currentNonce, false);
    }

    /**
     * @notice Burns tokens from the owner's balance and atomically redeems the underlying asset.
     * @param owner The address whose tokens will be burned and who receives the underlying asset.
     * @param amount The amount of tokens to burn (18 decimals).
     * @param vault The registered vault whose backing collateral is released and delivered.
     * @param erc3643Token The ERC-3643 token to unlock, deliver, and freeze.
     * @param nonce The owner's expected nonce; must equal nonces[owner].
     * @param deadline The deadline timestamp for the signature (must not be expired or too far in future).
     * @param signature The EIP-712 signature from a BURNER_ROLE holder authorizing this redemption.
     * @dev Atomic burn and redeem: destroys ERC-20, then delivers the underlying ERC-3643 into the
     *      owner's wallet and freezes it. The entire sequence is atomic.
     *      Flow:
     *      1. Validates parameters and deadline bounds
     *      2. Requires the named vault to be registered
     *      3. Verifies the owner has approved this contract for at least `amount`
     *      4. Builds and verifies the EIP-712 digest against a BURNER_ROLE signer and consumes the
     *         owner's nonce
     *      5. Spends allowance, burns the ERC-20, and calls vault.unlockAndFreeze()
     *      6. Decrements lockedByVault[vault]
     * @dev lockedByVault[vault] is operator-maintained; the removal-safety guard holds only if each
     *      burn names the vault its tokens were minted against. See docs/new_token_flow.md.
     */
    function burnAndRedeem(
        address owner,
        uint256 amount,
        address vault,
        address erc3643Token,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) external whenNotPaused nonReentrant {
        if (blocklisted[msg.sender]) revert AddressIsBlocklisted(msg.sender);
        if (blocklisted[owner]) revert AddressIsBlocklisted(owner);

        uint256 currentNonce = _validateAndConsumeBurn(
            BURN_REDEEM_TYPEHASH,
            owner,
            amount,
            vault,
            erc3643Token,
            nonce,
            deadline,
            signature
        );

        _spendAllowance(owner, address(this), amount);
        _burn(owner, amount);

        if (
            !IVaultContract(vault).unlockAndFreeze(erc3643Token, amount, owner)
        ) {
            revert VaultUnlockAndFreezeFailed(
                vault,
                erc3643Token,
                amount,
                owner
            );
        }
        lockedByVault[vault] -= amount;

        emit Burned(owner, amount, vault, erc3643Token, currentNonce, true);
    }

    /**
     * @notice Validates a burn request and consumes the owner's nonce.
     * @param typehash The EIP-712 typehash distinguishing the burn path.
     * @param owner The token owner whose tokens are burned.
     * @param amount The amount of tokens to burn.
     * @param vault The vault named in the signature.
     * @param erc3643Token The ERC-3643 token named in the signature.
     * @param nonce The owner's expected nonce; must equal nonces[owner].
     * @param deadline The signature deadline.
     * @param signature The EIP-712 signature to verify against a BURNER_ROLE holder.
     * @return currentNonce The nonce consumed for this burn.
     * @dev Validates inputs, deadline bounds, vault registration, allowance, and the BURNER_ROLE
     *      signature. The owner's nonce is consumed before any external call (CEI pattern). The
     *      recovered signer is used solely for the role check; the nonce is keyed on the owner.
     */
    function _validateAndConsumeBurn(
        bytes32 typehash,
        address owner,
        uint256 amount,
        address vault,
        address erc3643Token,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) private returns (uint256 currentNonce) {
        if (owner == address(0)) revert ZeroAddressNotAllowed();
        if (amount == 0) revert ZeroAmountNotAllowed();

        _checkDeadline(deadline);

        if (!registeredVaults[vault]) revert VaultNotRegistered(vault);

        uint256 currentAllowance = allowance(owner, address(this));
        if (currentAllowance < amount) {
            revert InsufficientAllowance(owner, amount, currentAllowance);
        }

        bytes32 structHash = keccak256(
            abi.encode(
                typehash,
                owner,
                amount,
                vault,
                erc3643Token,
                nonce,
                deadline
            )
        );
        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", _domainSeparator(), structHash)
        );

        (bool isValid, ) = _isValidSignature(digest, signature, BURNER_ROLE);
        if (!isValid) revert InvalidSignature();

        if (nonce != nonces[owner]) revert InvalidNonce(nonce, nonces[owner]);
        nonces[owner] = nonce + 1;
        currentNonce = nonce;
    }

    /**
     * @notice Enforces the signature deadline bounds.
     * @param deadline The deadline timestamp to validate.
     * @dev Reverts if the deadline has passed or is further than MAX_DEADLINE_DRIFT ahead.
     */
    function _checkDeadline(uint256 deadline) private view {
        if (block.timestamp > deadline) revert SignatureExpired();
        uint256 maxDeadline = block.timestamp + MAX_DEADLINE_DRIFT;
        if (deadline > maxDeadline) {
            revert DeadlineTooFarInFuture(deadline, maxDeadline);
        }
    }

    /**
     * @notice Verifies that an EIP-712 digest was signed by a holder of the required role.
     * @param digest The EIP-712 digest to verify.
     * @param signature The signature to verify against the digest.
     * @param requiredRole The role the recovered signer (or wallet) must hold.
     * @return isValid True if the signature is valid and from a holder of the required role.
     * @return signer The address that satisfied the role check (EOA signer or EIP-1271 wallet);
     *         address(0) when isValid is false.
     * @dev Verification flow:
     *      1. Try ECDSA recovery (works for EOA signatures); if the recovered address holds
     *         `requiredRole`, return (true, recovered)
     *      2. If signature length > 20, try EIP-1271 smart contract wallet verification:
     *         - First 20 bytes = wallet address (must have `requiredRole` and be a contract)
     *         - Remaining bytes = EIP-1271 signature data
     *         - On the magic value, return (true, walletAddress)
     *      3. Return (false, address(0)) if all verification paths fail
     *
     * @custom:security
     *      - EOA: Standard 65-byte ECDSA signature (r, s, v)
     *      - EIP-1271: abi.encodePacked(walletAddress, signatureData)
     *      - Uses tryRecover to avoid reverting on malformed signatures
     *      - The returned signer is used solely for the role check; the nonce is keyed on the
     *        subject (recipient for mint, owner for burn). Callers must ignore it when isValid is false
     */
    function _isValidSignature(
        bytes32 digest,
        bytes calldata signature,
        bytes32 requiredRole
    ) internal view returns (bool, address) {
        (address recovered, ECDSA.RecoverError error) = ECDSA.tryRecover(
            digest,
            signature
        );

        if (
            error == ECDSA.RecoverError.NoError &&
            hasRole(requiredRole, recovered)
        ) {
            return (true, recovered);
        }

        if (signature.length > 20) {
            address walletAddress = address(bytes20(signature[:20]));

            if (
                hasRole(requiredRole, walletAddress) &&
                walletAddress.code.length > 0
            ) {
                bytes calldata signatureData = signature[20:];

