    }

    /**
     * @notice Adds an address to the blocklist.
     * @param _account The address to blocklist.
     * @dev Only callable by DEFAULT_ADMIN_ROLE. Blocklisted addresses cannot send or receive tokens.
     *      Cannot blocklist the taxRecipient.
     */
    function addToBlocklist(
        address _account
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_account == address(0)) revert ZeroAddressNotAllowed();
        if (_account == taxRecipient) revert CannotBlocklistTaxRecipient();
        if (blocklisted[_account]) revert AddressAlreadyBlocklisted(_account);

        blocklisted[_account] = true;
        emit AddressBlocklisted(_account);
    }

    /**
     * @notice Removes an address from the blocklist.
     * @param _account The address to remove from blocklist.
     * @dev Only callable by DEFAULT_ADMIN_ROLE.
     */
    function removeFromBlocklist(
        address _account
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!blocklisted[_account]) revert AddressNotBlocklisted(_account);

        delete blocklisted[_account];
        emit AddressUnblocklisted(_account);
    }

    /**
     * @notice Sets the transfer tax rate.
     * @param _taxBps The tax rate in basis points (max 100 = 1%).
     * @dev Only callable by DEFAULT_ADMIN_ROLE. Set to 0 to disable transfer tax.
     */
    function setTransferTax(
        uint256 _taxBps
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_taxBps > MAX_TRANSFER_TAX_BPS) {
            revert TaxRateExceedsMaximum(_taxBps, MAX_TRANSFER_TAX_BPS);
        }

        uint256 oldTax = transferTaxBps;
        transferTaxBps = _taxBps;

        emit TransferTaxUpdated(oldTax, _taxBps);
    }

    /**
     * @notice Sets the tax recipient address.
     * @param _recipient The address that will receive collected taxes.
     * @dev Only callable by DEFAULT_ADMIN_ROLE. Cannot be a blocklisted address.
     */
    function setTaxRecipient(
        address _recipient
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_recipient == address(0)) revert ZeroAddressNotAllowed();
        if (blocklisted[_recipient]) revert AddressIsBlocklisted(_recipient);

        address oldRecipient = taxRecipient;
        taxRecipient = _recipient;

        emit TaxRecipientUpdated(oldRecipient, _recipient);
    }

    /**
     * @notice Calculates tax amount for a given amount and rate.
     * @param _amount The amount to calculate tax on.
     * @param _taxBps The tax rate in basis points.
     * @return taxAmount The calculated tax amount.
     */
    function calculateTax(
        uint256 _amount,
        uint256 _taxBps
    ) public pure returns (uint256 taxAmount) {
        return (_amount * _taxBps) / BPS_DENOMINATOR;
    }

    /**
     * @notice Sets the discount token address.
     * @param _token The address of the ERC20 token for discounts (address(0) to disable).
     * @dev Only callable by DEFAULT_ADMIN_ROLE.
     */
    function setDiscountToken(
        address _token
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_token != address(0)) {
            if (_token.code.length == 0) {
                revert NotAContract(_token);
            }
        }

        address oldToken = discountToken;
        discountToken = _token;

        emit DiscountTokenUpdated(oldToken, _token);
    }

    /**
     * @notice Sets the discount tiers configuration.
     * @param _thresholds Array of 3 thresholds (minimum token balance for each tier).
     * @param _discountBps Array of 3 discount percentages in basis points.
     * @dev Only callable by DEFAULT_ADMIN_ROLE. Tiers must be in ascending order.
     *      Threshold of 0 disables that tier.
     */
    function setDiscountTiers(
        uint256[3] calldata _thresholds,
        uint256[3] calldata _discountBps
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        uint256 lastNonZeroThreshold;
        uint256 lastNonZeroDiscount;
        bool seenZero;

        for (uint256 i = 0; i < 3; ++i) {
            uint256 th = _thresholds[i];
            uint256 disc = _discountBps[i];

            if (th == 0) {
                if (disc != 0) revert DiscountExceedsMaximum(disc, 0);
                seenZero = true;
            } else if (seenZero) {
                revert NonContiguousTiersNotAllowed();
            }

            if (disc > MAX_DISCOUNT_BPS) {
                revert DiscountExceedsMaximum(disc, MAX_DISCOUNT_BPS);
            }

            if (th != 0) {
                if (th <= lastNonZeroThreshold)
                    revert DiscountTiersNotAscending();
                if (disc <= lastNonZeroDiscount)
                    revert DiscountTiersNotAscending();

                lastNonZeroThreshold = th;
                lastNonZeroDiscount = disc;

                if (th > type(uint224).max) revert ThresholdExceedsMaximum();
            }

            _packedDiscountTiers[i] = (th << 32) | disc;
        }

        emit DiscountTiersUpdated(_thresholds, _discountBps);
    }

    /**
     * @notice Gets the discount percentage for a user based on their discount-token holdings.
     * @param _user The address to check.
     * @return discountBps The discount in basis points (0 if no discount applies).
     * @dev Reads the sender's live balance via a gas-capped staticcall. A failing or malicious
     *      discount token yields 0 (no discount) rather than reverting the transfer. Returns the
     *      highest tier the user qualifies for.
     */
    function getDiscountBps(
        address _user
    ) public view returns (uint256 discountBps) {
        if (discountToken == address(0)) return 0;

        uint256 userBalance = _safeBalanceOf(discountToken, _user, 10_000);

        uint256 p = _packedDiscountTiers[2];
        uint256 threshold = p >> 32;
        uint256 discBps = p & _DISCOUNT_MASK;
        if (threshold != 0 && userBalance >= threshold) return discBps;

        p = _packedDiscountTiers[1];
        threshold = p >> 32;
        discBps = p & _DISCOUNT_MASK;
        if (threshold != 0 && userBalance >= threshold) return discBps;

        p = _packedDiscountTiers[0];
        threshold = p >> 32;
        discBps = p & _DISCOUNT_MASK;
        if (threshold != 0 && userBalance >= threshold) return discBps;

        return 0;
    }

    /**
     * @notice Gets the discount tiers configuration.
     * @return thresholds Array of tier thresholds.
     * @return discounts Array of tier discount percentages in basis points.
     */
    function getDiscountTiers()
        external
        view
        returns (uint256[3] memory thresholds, uint256[3] memory discounts)
    {
        for (uint256 i = 0; i < 3; ++i) {
            uint256 p = _packedDiscountTiers[i];
            thresholds[i] = p >> 32;
            discounts[i] = p & _DISCOUNT_MASK;
        }

        return (thresholds, discounts);
    }

    /**
     * @notice Safely retrieves token balance with gas limit protection.
     * @param token The ERC20 token address to query.
     * @param account The account to check balance for.
     * @param gasCap Maximum gas to use for the external call.
     * @return bal The token balance, or 0 if the call fails or returns invalid data.
     * @dev Uses staticcall with gas cap to prevent:
     *      - DoS from malicious tokens that consume excessive gas
     *      - Reverts from broken/non-standard token implementations
     */
    function _safeBalanceOf(
        address token,
        address account,
        uint256 gasCap
    ) internal view returns (uint256 bal) {
        if (token == address(0) || token.code.length == 0) return 0;

        (bool ok, bytes memory ret) = token.staticcall{gas: gasCap}(
            abi.encodeWithSelector(IERC20.balanceOf.selector, account)
        );

        if (!ok || ret.length < 32) return 0;

        bal = abi.decode(ret, (uint256));
    }

    /**
     * @notice Adds an address to the tax exemption list.
     * @param _account The address to exempt from transfer taxes.
     * @dev Only callable by DEFAULT_ADMIN_ROLE.
     */
    function addTaxExemptAddress(
        address _account
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_account == address(0)) revert ZeroAddressNotAllowed();
        if (taxExemptAddresses[_account])
            revert AddressAlreadyTaxExempt(_account);

        taxExemptAddresses[_account] = true;

        emit TaxExemptAdded(_account);
    }

    /**
     * @notice Removes an address from the tax exemption list.
     * @param _account The address to remove.
     * @dev Only callable by DEFAULT_ADMIN_ROLE.
     */
    function removeTaxExemptAddress(
        address _account
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!taxExemptAddresses[_account]) revert AddressNotTaxExempt(_account);

        delete taxExemptAddresses[_account];

        emit TaxExemptRemoved(_account);
    }

    /**
     * @notice Rescues ERC20 tokens stuck in this contract.
     * @param _token The address of the token to rescue.
     * @param _to The address to send the rescued tokens to.
     * @param _amount The amount of tokens to rescue.
     * @dev Only callable by DEFAULT_ADMIN_ROLE. Since this contract does not hold/lock any tokens
     *      by design, any tokens sent here are considered stuck and can be rescued.
     */
    function rescueTokens(
        address _token,
        address _to,
        uint256 _amount
    ) external onlyRole(DEFAULT_ADMIN_ROLE) whenNotPaused nonReentrant {
        if (_token == address(0)) revert ZeroAddressNotAllowed();
        if (_to == address(0)) revert ZeroAddressNotAllowed();

        SafeERC20.safeTransfer(IERC20(_token), _to, _amount);

        emit TokensRescued(_token, _to, _amount);
    }

    /**
     * @notice Transfers tokens on behalf of `from` using the caller's allowance.
     * @param from The token owner whose balance is debited.
     * @param to The recipient address.
     * @param amount The amount to transfer.
     * @return True on success.
     * @dev Rejects a blocklisted spender (msg.sender) before the allowance is spent. The
     *      _beforeTokenTransfer hook only sees the token `from`/`to`, so without this guard a
     *      blocklisted spender holding an allowance from an unblocked owner could move tokens
     *      between two unblocked parties. This closes that delegated-spending gap.
     */
    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) public virtual override returns (bool) {
        if (blocklisted[msg.sender]) revert AddressIsBlocklisted(msg.sender);
        return super.transferFrom(from, to, amount);
    }

    /**
     * @notice Hook called before any token transfer.
     * @param from The sender (address(0) for mints).
     * @param to The recipient (address(0) for burns).
     * @param amount The amount being transferred.
     * @dev Enforces pause state and blocklist.
     *      Blocklist check: real transfers verify both sender and recipient, mints verify the
     *      recipient. A burn (to == address(0)) destroys tokens rather than moving them to another
     *      party, so the FROM-side blocklist check is skipped on burns; this lets sanctioned supply
     *      be retired and prevents collateral accounting from being permanently pinned by a
     *      blocklisted holder. The blocklist still blocks all real transfers and mints. Because this
     *      hook does not see msg.sender, the delegated-spend guard for a blocklisted spender lives
     *      in transferFrom().
     */
    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual override whenNotPaused {
        super._beforeTokenTransfer(from, to, amount);

        if (from != address(0) && to != address(0)) {
            if (blocklisted[from]) {
                revert AddressIsBlocklisted(from);
            }
        }

        if (to != address(0)) {
            if (to != taxRecipient) {
                if (blocklisted[to]) {
                    revert AddressIsBlocklisted(to);
                }
            }
        }
    }

    /**
     * @notice Transfer with tax and discount logic.
     * @param from The sender address.
     * @param to The recipient address.
     * @param amount The amount to transfer.
     * @dev Tax exemptions:
     *      - Transfers to/from taxRecipient (prevents loops)
     *      - Tax exempt addresses (sender OR receiver)
     *      - transferTaxBps is 0
     *
     *      Discount: Applied based on sender's discount token balance.
     */
    function _transfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual override {
        if (to == taxRecipient || from == taxRecipient) {
            super._transfer(from, to, amount);
            return;
        }

        if (taxExemptAddresses[from] || taxExemptAddresses[to]) {
            super._transfer(from, to, amount);
            return;
        }

        if (transferTaxBps > 0) {
            uint256 baseTaxAmount = calculateTax(amount, transferTaxBps);

            if (baseTaxAmount > 0) {
                uint256 actualTaxAmount = baseTaxAmount;

                uint256 userDiscountBps = getDiscountBps(from);
                if (userDiscountBps > 0) {
                    uint256 discountAmount = (baseTaxAmount * userDiscountBps) /
                        BPS_DENOMINATOR;
                    actualTaxAmount = baseTaxAmount - discountAmount;

                    emit TransferTaxDiscountApplied(
                        from,
                        to,
                        baseTaxAmount,
                        actualTaxAmount,
                        userDiscountBps
                    );
                }

                if (actualTaxAmount > 0) {
                    uint256 amountAfterTax = amount - actualTaxAmount;

                    super._transfer(from, taxRecipient, actualTaxAmount);
                    super._transfer(from, to, amountAfterTax);

                    emit TransferTaxCollected(from, to, actualTaxAmount);
                    return;
                }
            }
        }

        super._transfer(from, to, amount);
    }
}

