    }

    // ---------------- art ----------------
    function _base(string memory f) private pure returns (string memory) {
        return string.concat(
            string.concat('<rect x="1" y="1" width="4" height="5" fill="#111"/>', '<rect x="19" y="1" width="4" height="5" fill="#111"/>', '<rect x="2" y="2" width="2" height="3" fill="#E8DCC8"/>', '<rect x="20" y="2" width="2" height="3" fill="#E8DCC8"/>'),
            string.concat('<rect x="1" y="8" width="3" height="3" fill="#111"/>', '<rect x="20" y="8" width="3" height="3" fill="#111"/>', string.concat('<rect x="2" y="9" width="1" height="1" fill="', f, '"/>'), string.concat('<rect x="21" y="9" width="1" height="1" fill="', f, '"/>')),
