    }
    function _pattern(uint256 k) private pure returns (string memory) {
        if (k == 0) return "";
        if (k == 1) return string.concat('<g fill-opacity=".5">', '<rect x="11" y="6" width="2" height="5" fill="#FFFFFF"/>', '</g>');
        if (k == 2) return string.concat('<g fill-opacity=".25">', '<rect x="6" y="8" width="2" height="2" fill="#000"/>', '<rect x="16" y="15" width="2" height="2" fill="#000"/>', '<rect x="15" y="8" width="1" height="1" fill="#000"/>', '<rect x="7" y="16" width="1" height="1" fill="#000"/>', '</g>');
        return string.concat('<g fill-opacity=".25">', '<rect x="5" y="8" width="6" height="6" fill="#000"/>', '<rect x="13" y="8" width="6" height="6" fill="#000"/>', '</g>');
