        if (k == 5) return string.concat('<rect x="7" y="10" width="3" height="2" fill="#F0B90B"/>', '<rect x="14" y="10" width="3" height="2" fill="#F0B90B"/>', '<rect x="7" y="10" width="3" height="1" fill="#111"/>', '<rect x="14" y="10" width="3" height="1" fill="#111"/>');
