            string.concat('"},{"trait_type":"Mouth","value":"', _mouthN(t[5]), '"},{"trait_type":"Collar","value":"', _collarN(t[6]), '"}]')
        );
        string memory json = string.concat(
            '{"name":"Agent Goat #', _str(id), '","description":"', DESC,
            '","image":"data:image/svg+xml;base64,', _b64(bytes(_svg(s))), '","attributes":', attrs, '}'
        );
