    }
    function contractURI() external view returns (string memory) {
        string memory json = string.concat(
            '{"name":"Agent Goats","description":"', DESC,
            '","image":"data:image/svg+xml;base64,', _b64(bytes(_draw([uint256(1), 6, 0, 6, 7, 4, 2], 0))),
