        if (k == 4) return string.concat('<rect x="7" y="5" width="1" height="1" fill="#E63946"/>', '<rect x="9" y="5" width="1" height="1" fill="#E63946"/>', '<rect x="7" y="6" width="3" height="1" fill="#E63946"/>', '<rect x="15" y="5" width="1" height="1" fill="#E63946"/>', '<rect x="17" y="5" width="1" height="1" fill="#E63946"/>', '<rect x="15" y="6" width="3" height="1" fill="#E63946"/>');
