        if (k == 6) return string.concat('<rect x="6" y="4" width="4" height="4" fill="#FFFFFF"/>', '<rect x="14" y="4" width="4" height="4" fill="#FFFFFF"/>', '<rect x="7" y="5" width="2" height="2" fill="#FF3B30"/>', '<rect x="15" y="5" width="2" height="2" fill="#FF3B30"/>', '<rect x="0" y="5" width="5" height="1" fill="#FF3B30"/>', '<rect x="19" y="5" width="5" height="1" fill="#FF3B30"/>');
