        if (k == 1) return string.concat(string.concat('<rect x="5" y="4" width="14" height="3" fill="', acc, '"/>'), string.concat('<rect x="16" y="6" width="6" height="1" fill="', acc, '"/>'), '<rect x="5" y="7" width="14" height="1" fill="#111"/>');
        if (k == 2) return string.concat(string.concat('<rect x="5" y="3" width="14" height="4" fill="', acc, '"/>'), '<rect x="5" y="6" width="14" height="1" fill="#111"/>', '<rect x="11" y="1" width="2" height="2" fill="#fff"/>');
        if (k == 3) return string.concat('<rect x="14" y="5" width="2" height="3" fill="#E63946"/>', '<rect x="18" y="5" width="2" height="3" fill="#E63946"/>', '<rect x="16" y="6" width="2" height="1" fill="#B0202C"/>');
