        return string.concat('<rect x="6" y="1" width="12" height="4" fill="#111"/>', '<rect x="7" y="2" width="10" height="2" fill="#FFD700"/>', '<rect x="7" y="0" width="2" height="2" fill="#FFD700"/>', '<rect x="11" y="0" width="2" height="2" fill="#FFD700"/>', '<rect x="15" y="0" width="2" height="2" fill="#FFD700"/>', '<rect x="11" y="2" width="2" height="1" fill="#E63946"/>');
