    function _collar(uint256 k) private pure returns (string memory) {
        if (k == 0) return "";
        if (k == 1) return string.concat('<rect x="6" y="19" width="12" height="1" fill="#E63946"/>', '<rect x="11" y="20" width="2" height="2" fill="#FFD700"/>');
        if (k == 2) return '<rect x="7" y="20" width="10" height="1" fill="#F0B90B"/>';
        if (k == 3) return string.concat('<rect x="7" y="20" width="10" height="1" fill="#C0C0C0"/>', '<rect x="11" y="21" width="2" height="2" fill="#F7931A"/>');
        return string.concat('<rect x="7" y="20" width="10" height="1" fill="#9BE7FF"/>', '<rect x="11" y="21" width="2" height="1" fill="#fff"/>');
    }
    function _svg(uint256 s) private pure returns (string memory) {
        return _draw(_traits(s), (s >> 104) % 8);
    }
    function _draw(uint256[7] memory t, uint256 a) private pure returns (string memory) {
        string memory acc = ["#E63946","#2F80ED","#111111","#F0B90B","#7B2CBF","#2A9D8F","#F4A261","#FFFFFF"][a];
        return string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" shape-rendering="crispEdges">',
            string.concat('<rect x="0" y="0" width="24" height="24" fill="', _bgC(t[0]), '"/>'), _base(_furC(t[1])), _pattern(t[2]),
            string.concat(_face(), _eyes(t[3]), _mouth(t[5]), _collar(t[6]), _head(t[4], acc)),
            '</svg>'
        );
    }
    function tokenURI(uint256 id) external view returns (string memory) {
        ownerOf(id);
        uint256 s = _seed[id];
        uint256[7] memory t = _traits(s);
        string memory attrs = string.concat(
            string.concat('[{"trait_type":"Background","value":"', _bgN(t[0]), '"},{"trait_type":"Skin","value":"', _furN(t[1]), '"},{"trait_type":"Pattern","value":"', _patN(t[2])),
            string.concat('"},{"trait_type":"Eyes","value":"', _eyesN(t[3]), '"},{"trait_type":"Headwear","value":"', _headN(t[4])),
            string.concat('"},{"trait_type":"Mouth","value":"', _mouthN(t[5]), '"},{"trait_type":"Collar","value":"', _collarN(t[6]), '"}]')
        );
        string memory json = string.concat(
            '{"name":"Agent Frog #', _str(id), '","description":"', DESC,
            '","image":"data:image/svg+xml;base64,', _b64(bytes(_svg(s))), '","attributes":', attrs, '}'
        );
        return string.concat("data:application/json;base64,", _b64(bytes(json)));
    }
    function contractURI() external view returns (string memory) {
        string memory json = string.concat(
            '{"name":"Agent Frogs","description":"', DESC,
            '","image":"data:image/svg+xml;base64,', _b64(bytes(_draw([uint256(1), 6, 0, 6, 7, 4, 2], 0))),
            '","seller_fee_basis_points":500,"fee_recipient":"', _hex(payout), '"}'
        );
        return string.concat("data:application/json;base64,", _b64(bytes(json)));
    }

    // ---------------- utils ----------------
    function _hex(address a) private pure returns (string memory) {
        bytes memory h = "0123456789abcdef"; bytes memory r = new bytes(42);
        r[0] = "0"; r[1] = "x";
        for (uint256 i; i < 20; i++) {
            uint8 b = uint8(uint160(a) >> (8 * (19 - i)));
            r[2 + i * 2] = h[b >> 4]; r[3 + i * 2] = h[b & 15];
        }
        return string(r);
    }
    function _str(uint256 v) private pure returns (string memory) {
        if (v == 0) return "0";
        uint256 l; for (uint256 t = v; t > 0; t /= 10) l++;
        bytes memory b = new bytes(l);
        while (v > 0) { b[--l] = bytes1(uint8(48 + v % 10)); v /= 10; }
        return string(b);
    }
    function _b64(bytes memory data) private pure returns (string memory) {
        bytes memory T = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        uint256 len = data.length; if (len == 0) return "";
        bytes memory r = new bytes(4 * ((len + 2) / 3));
        uint256 j;
        for (uint256 i; i < len; i += 3) {
            uint256 a = uint8(data[i]);
            uint256 b = i + 1 < len ? uint8(data[i + 1]) : 0;
            uint256 c = i + 2 < len ? uint8(data[i + 2]) : 0;
            uint256 n = (a << 16) | (b << 8) | c;
            r[j++] = T[(n >> 18) & 63]; r[j++] = T[(n >> 12) & 63];
            r[j++] = i + 1 < len ? T[(n >> 6) & 63] : bytes1("=");
            r[j++] = i + 2 < len ? T[n & 63] : bytes1("=");
        }
        return string(r);
    }
}

