    uint256 public totalSupply;
    uint256 public freeClaimed;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) public getApproved;
    mapping(address => mapping(address => bool)) public isApprovedForAll;
    mapping(address => uint256) public mintedBy;
    mapping(uint256 => uint256) private _seed;

    event Transfer(address indexed from, address indexed to, uint256 indexed id);
    event Approval(address indexed o, address indexed s, uint256 indexed id);
    event ApprovalForAll(address indexed o, address indexed op, bool ok);
    event OwnershipTransferred(address indexed prev, address indexed next);

    constructor(address _owner, address _payout) {
        owner = _owner; payout = _payout;
        emit OwnershipTransferred(address(0), _owner);
    }

    modifier onlyOwner() { require(msg.sender == owner, "owner"); _; }

    // ---------------- mint ----------------
    function cost(address who, uint256 qty) public view returns (uint256) {
        if (qty == 0) return 0;
        bool free = mintedBy[who] == 0 && freeClaimed < FREE_SUPPLY;
        return price * (free ? qty - 1 : qty);
    }

    function mint(uint256 qty) external payable {
        require(mintOpen, "closed");
        require(qty > 0 && mintedBy[msg.sender] + qty <= MAX_PER_WALLET, "limit");
        require(totalSupply + qty <= MAX_SUPPLY, "sold out");
        require(AGENT_ID.balanceOf(msg.sender) > 0, "need .ai Agent ID");
        uint256 c = cost(msg.sender, qty);
        require(msg.value >= c, "price");
        if (mintedBy[msg.sender] == 0 && freeClaimed < FREE_SUPPLY) freeClaimed++;
        mintedBy[msg.sender] += qty;
        for (uint256 i; i < qty; i++) {
            uint256 id = ++totalSupply;
            _seed[id] = uint256(keccak256(abi.encode(id, msg.sender, block.prevrandao, block.timestamp)));
            _owners[id] = msg.sender;
            _balances[msg.sender]++;
            emit Transfer(address(0), msg.sender, id);
        }
        if (msg.value > c) payable(msg.sender).transfer(msg.value - c);
    }

    function withdraw() external { payable(payout).transfer(address(this).balance); }
    function setPrice(uint256 p) external onlyOwner { price = p; }
    function setMintOpen(bool o) external onlyOwner { mintOpen = o; }
    function transferOwnership(address n) external onlyOwner { emit OwnershipTransferred(owner, n); owner = n; }

    // ---------------- ERC721 ----------------
    function balanceOf(address a) external view returns (uint256) { require(a != address(0)); return _balances[a]; }
    function ownerOf(uint256 id) public view returns (address o) { o = _owners[id]; require(o != address(0), "none"); }
    function approve(address s, uint256 id) external {
        address o = ownerOf(id);
        require(msg.sender == o || isApprovedForAll[o][msg.sender], "auth");
        getApproved[id] = s; emit Approval(o, s, id);
    }
    function setApprovalForAll(address op, bool ok) external { isApprovedForAll[msg.sender][op] = ok; emit ApprovalForAll(msg.sender, op, ok); }
    function transferFrom(address f, address t, uint256 id) public {
        require(f == ownerOf(id), "from");
        require(t != address(0), "to");
        require(msg.sender == f || isApprovedForAll[f][msg.sender] || msg.sender == getApproved[id], "auth");
        _balances[f]--; _balances[t]++; _owners[id] = t; delete getApproved[id];
        emit Transfer(f, t, id);
    }
    function safeTransferFrom(address f, address t, uint256 id) external { safeTransferFrom(f, t, id, ""); }
    function safeTransferFrom(address f, address t, uint256 id, bytes memory d) public {
        transferFrom(f, t, id);
        if (t.code.length > 0) require(IReceiver(t).onERC721Received(msg.sender, f, id, d) == IReceiver.onERC721Received.selector, "recv");
    }
    function supportsInterface(bytes4 i) external pure returns (bool) {
        return i == 0x01ffc9a7 || i == 0x80ac58cd || i == 0x5b5e139f || i == 0x2a55205a;
    }
    function royaltyInfo(uint256, uint256 sale) external view returns (address, uint256) { return (payout, sale * ROYALTY_BPS / 10000); }

    // ---------------- traits ----------------
    function _pick(uint256 r, uint8[8] memory cum, uint256 n) private pure returns (uint256) {
        r = (r & 0xffff) % 100;
        for (uint256 i; i < n; i++) if (r < cum[i]) return i;
        return n - 1;
    }
    function _traits(uint256 s) private pure returns (uint256[7] memory t) {
        t[0] = (s & 0xff) % 8;                                                   // background
        t[1] = _pick(s >> 8, [uint8(20), 38, 54, 68, 80, 90, 97, 100], 8);       // fur
        t[2] = _pick(s >> 24, [uint8(40), 65, 82, 100, 100, 100, 100, 100], 4);  // pattern
        t[3] = _pick(s >> 40, [uint8(24), 44, 58, 70, 81, 90, 96, 100], 8);      // eyes
        t[4] = _pick(s >> 56, [uint8(30), 44, 57, 69, 80, 88, 94, 100], 8);      // headwear
        t[5] = _pick(s >> 72, [uint8(32), 56, 76, 90, 100, 100, 100, 100], 5);   // mouth
        t[6] = _pick(s >> 88, [uint8(45), 70, 84, 95, 100, 100, 100, 100], 5);   // collar
    }
    function _bgC(uint256 i) private pure returns (string memory) {
        return ["#F6C1C7","#F0B90B","#1E2026","#8EC5E8","#9ED9A0","#B9A2E8","#F5E6CC","#E26D5C"][i];
