            string.concat('<rect x="8" y="14" width="8" height="6" fill="#FFFFFF" fill-opacity=".35"/>', '<rect x="4" y="12" width="2" height="6" fill="#000000" fill-opacity=".18"/>', '<rect x="18" y="12" width="2" height="6" fill="#000000" fill-opacity=".18"/>'),
