        if (k == 1) return string.concat('<rect x="6" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="14" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="7" y="10" width="2" height="2" fill="#4FB3FF"/>', '<rect x="15" y="10" width="2" height="2" fill="#4FB3FF"/>', '<rect x="7" y="10" width="1" height="1" fill="#111"/>', '<rect x="15" y="10" width="1" height="1" fill="#111"/>');
        if (k == 2) return string.concat('<rect x="6" y="11" width="4" height="1" fill="#111"/>', '<rect x="14" y="11" width="4" height="1" fill="#111"/>');
        if (k == 3) return string.concat('<rect x="5" y="9" width="14" height="3" fill="#111"/>', '<rect x="7" y="10" width="2" height="1" fill="#888"/>', '<rect x="15" y="10" width="2" height="1" fill="#888"/>');
        if (k == 4) return string.concat('<rect x="6" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="14" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="7" y="10" width="1" height="1" fill="#E63946"/>', '<rect x="9" y="10" width="1" height="1" fill="#E63946"/>', '<rect x="7" y="11" width="3" height="1" fill="#E63946"/>', '<rect x="15" y="10" width="1" height="1" fill="#E63946"/>', '<rect x="17" y="10" width="1" height="1" fill="#E63946"/>', '<rect x="15" y="11" width="3" height="1" fill="#E63946"/>');
        if (k == 5) return string.concat('<rect x="6" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="14" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="7" y="10" width="2" height="2" fill="#F0B90B"/>', '<rect x="15" y="10" width="2" height="2" fill="#F0B90B"/>', '<rect x="7" y="10" width="1" height="1" fill="#111"/>', '<rect x="15" y="10" width="1" height="1" fill="#111"/>');
        if (k == 6) return string.concat('<rect x="6" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="14" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="7" y="10" width="2" height="2" fill="#FF3B30"/>', '<rect x="15" y="10" width="2" height="2" fill="#FF3B30"/>', '<rect x="0" y="10" width="6" height="1" fill="#FF3B30"/>', '<rect x="18" y="10" width="6" height="1" fill="#FF3B30"/>');
        return string.concat('<rect x="6" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="14" y="9" width="4" height="4" fill="#FFFFFF"/>', '<rect x="7" y="10" width="2" height="2" fill="#9BE7FF"/>', '<rect x="15" y="10" width="2" height="2" fill="#9BE7FF"/>', '<rect x="7" y="10" width="1" height="1" fill="#111"/>', '<rect x="15" y="10" width="1" height="1" fill="#111"/>');
