    function _mouth(uint256 k) private pure returns (string memory) {
        if (k == 0) return "";
        if (k == 1) return string.concat('<rect x="11" y="15" width="2" height="1" fill="#B95C06"/>', '<rect x="11" y="16" width="2" height="1" fill="#111"/>');
        if (k == 2) return string.concat('<rect x="11" y="13" width="2" height="1" fill="#FFD700"/>', '<rect x="11" y="14" width="2" height="1" fill="#FFD700"/>');
