import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {SignatureVerifier} from "./SignatureVerifier.sol";
import {IERC3009WithERC1271} from "./interfaces/IERC3009WithERC1271.sol";

abstract contract EIP3009WithERC1271 is ERC20, EIP712, IERC3009WithERC1271 {
    bytes32 public constant TRANSFER_WITH_AUTHORIZATION_TYPEHASH =
        keccak256("TransferWithAuthorization(address from,address to,uint256 value,uint256 validAfter,uint256 validBefore,bytes32 nonce)");
    bytes32 public constant RECEIVE_WITH_AUTHORIZATION_TYPEHASH =
        keccak256("ReceiveWithAuthorization(address from,address to,uint256 value,uint256 validAfter,uint256 validBefore,bytes32 nonce)");
    bytes32 public constant CANCEL_AUTHORIZATION_TYPEHASH =
        keccak256("CancelAuthorization(address authorizer,bytes32 nonce)");

    mapping(address => mapping(bytes32 => bool)) private _authorizationStates;

    error EIP3009InvalidSignature();
    error EIP3009AuthorizationAlreadyUsed(address authorizer, bytes32 nonce);
    error EIP3009AuthorizationNotYetValid(uint256 validAfter, uint256 currentTime);
    error EIP3009AuthorizationExpired(uint256 validBefore, uint256 currentTime);
    error EIP3009CallerMustBePayee(address caller, address payee);

    constructor(string memory name_, string memory symbol_) ERC20(name_, symbol_) EIP712(name_, "1") {}

    function authorizationState(address authorizer, bytes32 nonce) external view returns (bool) {
        return _authorizationStates[authorizer][nonce];
    }

    function transferWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        transferWithAuthorization(from, to, value, validAfter, validBefore, nonce, SignatureVerifier.packRsv(v, r, s));
    }

    function transferWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        bytes memory signature
    ) public {
        _transferWithAuthorization(TRANSFER_WITH_AUTHORIZATION_TYPEHASH, from, to, value, validAfter, validBefore, nonce, signature);
    }

    function receiveWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        receiveWithAuthorization(from, to, value, validAfter, validBefore, nonce, SignatureVerifier.packRsv(v, r, s));
    }

    function receiveWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        bytes memory signature
    ) public {
        if (msg.sender != to) {
            revert EIP3009CallerMustBePayee(msg.sender, to);
        }

        _transferWithAuthorization(RECEIVE_WITH_AUTHORIZATION_TYPEHASH, from, to, value, validAfter, validBefore, nonce, signature);
    }

    function cancelAuthorization(address authorizer, bytes32 nonce, uint8 v, bytes32 r, bytes32 s) external {
        cancelAuthorization(authorizer, nonce, SignatureVerifier.packRsv(v, r, s));
    }

    function cancelAuthorization(address authorizer, bytes32 nonce, bytes memory signature) public {
        if (_authorizationStates[authorizer][nonce]) {
            revert EIP3009AuthorizationAlreadyUsed(authorizer, nonce);
        }

        // Defense-in-depth (audit F-PR3-08): claim the nonce slot BEFORE
        // sig verification. Today the SignatureVerifier dispatches the
        // ERC-1271 callback via STATICCALL (because OZ IERC1271.isValidSignature
        // is declared `external view`), which means a state-changing reentry
        // would revert in the static frame anyway. This CEI ordering removes
        // dependence on that opcode choice — if SignatureVerifier is ever
        // refactored to a low-level `call` (e.g. to capture revertdata or
        // support a non-view 1271 variant) the contract stays safe. See
        // docs/audits/2026-05-28-pr2-security-review/NONCE-REENTRANCY-REVIEW.md.
        _authorizationStates[authorizer][nonce] = true;

        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(CANCEL_AUTHORIZATION_TYPEHASH, authorizer, nonce)));
        (bool valid,) = SignatureVerifier.isValidSignature(authorizer, digest, signature);
        if (!valid) {
            // Roll back the speculative claim — the nonce was not actually
            // authorized to be cancelled by `authorizer`.
            _authorizationStates[authorizer][nonce] = false;
            revert EIP3009InvalidSignature();
        }

        emit AuthorizationCanceled(authorizer, nonce);
    }

    function _transferWithAuthorization(
        bytes32 typehash,
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        bytes memory signature
    ) internal {
        if (block.timestamp <= validAfter) {
            revert EIP3009AuthorizationNotYetValid(validAfter, block.timestamp);
        }
        if (block.timestamp >= validBefore) {
            revert EIP3009AuthorizationExpired(validBefore, block.timestamp);
        }
        if (_authorizationStates[from][nonce]) {
            revert EIP3009AuthorizationAlreadyUsed(from, nonce);
        }

        // Defense-in-depth (audit F-PR3-08): same CEI rationale as
        // cancelAuthorization above. The STATICCALL dispatch in
        // SignatureVerifier already prevents the reentrant double-transfer
        // exploit for the current OZ IERC1271 interface; this ordering
        // removes the contract's dependence on that opcode choice so a
        // future refactor of SignatureVerifier cannot silently re-open the
        // attack surface.
        _authorizationStates[from][nonce] = true;

        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(typehash, from, to, value, validAfter, validBefore, nonce)));
        (bool valid,) = SignatureVerifier.isValidSignature(from, digest, signature);
        if (!valid) {
            // Roll back the speculative claim — the signature did not actually
            // authorize this transfer, so the nonce must remain reusable.
            _authorizationStates[from][nonce] = false;
            revert EIP3009InvalidSignature();
        }

        emit AuthorizationUsed(from, nonce);
        _transfer(from, to, value);
    }
}


