// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IXERC20} from "../interfaces/IXERC20.sol";
import {EIP3009WithERC1271} from "./EIP3009WithERC1271.sol";
import {SignatureVerifier} from "./SignatureVerifier.sol";
import {IHTEAXERC20Permit} from "./interfaces/IHTEAXERC20Permit.sol";

contract HTEAXERC20 is EIP3009WithERC1271, Ownable2Step, IXERC20, IERC20Permit, IHTEAXERC20Permit {
    uint256 private constant _DURATION = 1 days;
    bytes32 public constant PERMIT_TYPEHASH =
        keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");

    address public immutable FACTORY;
    address public lockbox;

    mapping(address => Bridge) public bridges;
    mapping(address => uint256) private _nonces;

    error ERC2612ExpiredSignature(uint256 deadline);
    error ERC2612InvalidSigner(address recovered, address owner);
    error IXERC20_LockboxAlreadySet();
    error IXERC20_ZeroAddress();

    constructor(string memory name_, string memory symbol_, address factory_) EIP3009WithERC1271(name_, symbol_) {
        FACTORY = factory_;
        _transferOwnership(factory_);
    }

    /// @dev Disables {Ownable.renounceOwnership} so the Safe cannot accidentally
    /// brick `setLimits` (and therefore the emergency-rollback playbook in
    /// `docs/emergency-rollback.md`). Audit C-CTR-10.
    function renounceOwnership() public view override onlyOwner {
        revert("HTEAXERC20: renounceOwnership disabled");
    }

    function mint(address user, uint256 amount) public {
        _mintWithCaller(msg.sender, user, amount);
    }

    function burn(address user, uint256 amount) public {
        if (msg.sender != user) {
            _spendAllowance(user, msg.sender, amount);
        }

        _burnWithCaller(msg.sender, user, amount);
    }

    /// @dev Lockbox is one-shot: a successful call sets `lockbox` permanently.
    /// A second call (even from FACTORY) reverts with {IXERC20_LockboxAlreadySet}.
    /// Audit L-CTR-03.
    function setLockbox(address lockbox_) public {
        if (msg.sender != FACTORY) {
            revert IXERC20_NotFactory();
        }
        if (lockbox != address(0)) {
            revert IXERC20_LockboxAlreadySet();
        }
        if (lockbox_ == address(0)) {
            revert IXERC20_ZeroAddress();
        }
        lockbox = lockbox_;
        emit LockboxSet(lockbox_);
    }

    function setLimits(address bridge, uint256 mintingLimit, uint256 burningLimit) external onlyOwner {
        if (bridge == address(0)) {
            revert IXERC20_ZeroAddress();
        }
        if (mintingLimit > (type(uint256).max / 2) || burningLimit > (type(uint256).max / 2)) {
            revert IXERC20_LimitsTooHigh();
        }

        _changeMinterLimit(bridge, mintingLimit);
        _changeBurnerLimit(bridge, burningLimit);
        emit BridgeLimitsSet(mintingLimit, burningLimit, bridge);
    }

    function mintingMaxLimitOf(address bridge) public view returns (uint256) {
        return bridges[bridge].minterParams.maxLimit;
    }

    function burningMaxLimitOf(address bridge) public view returns (uint256) {
        return bridges[bridge].burnerParams.maxLimit;
    }

    function mintingCurrentLimitOf(address bridge) public view returns (uint256) {
        return _getCurrentLimit(
            bridges[bridge].minterParams.currentLimit,
            bridges[bridge].minterParams.maxLimit,
            bridges[bridge].minterParams.timestamp,
            bridges[bridge].minterParams.ratePerSecond
        );
    }

    function burningCurrentLimitOf(address bridge) public view returns (uint256) {
        return _getCurrentLimit(
            bridges[bridge].burnerParams.currentLimit,
            bridges[bridge].burnerParams.maxLimit,
            bridges[bridge].burnerParams.timestamp,
            bridges[bridge].burnerParams.ratePerSecond
        );
    }

    function permit(
        address owner,
        address spender,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        permit(owner, spender, value, deadline, SignatureVerifier.packRsv(v, r, s));
    }

    function permit(address owner, address spender, uint256 value, uint256 deadline, bytes memory signature) public {
        if (block.timestamp > deadline) {
            revert ERC2612ExpiredSignature(deadline);
        }

        // Defense-in-depth (audit L-CTR-02 + F-PR3-08): post-increment the
        // nonce BEFORE the external sig verification call. Today the
        // SignatureVerifier ERC-1271 callback dispatches via STATICCALL
        // (because OZ IERC1271.isValidSignature is `external view`), so a
        // state-changing reentry would already revert; this ordering matches
        // OZ ERC20Permit._useNonce and removes dependence on that opcode
        // choice if SignatureVerifier is ever refactored to a low-level
        // `call`. See
        // docs/audits/2026-05-28-pr2-security-review/NONCE-REENTRANCY-REVIEW.md.
        uint256 currentNonce = _nonces[owner]++;
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, currentNonce, deadline)));
        (bool valid, address recovered) = SignatureVerifier.isValidSignature(owner, digest, signature);
        if (!valid) {
            // Roll back the speculative nonce increment so a failed permit
            // does not burn the user's next nonce.
            _nonces[owner] = currentNonce;
            revert ERC2612InvalidSigner(recovered, owner);
        }

        _approve(owner, spender, value);
    }

    function nonces(address owner) public view returns (uint256) {
        return _nonces[owner];
    }

    function DOMAIN_SEPARATOR() external view returns (bytes32) {
        return _domainSeparatorV4();
    }

    /// @dev Inherits Ownable2Step semantics: `transferOwnership` only sets
    /// `pendingOwner`. The Safe must subsequently call {acceptOwnership} to
    /// finalize. Audit L-CTR-04.

    function _useMinterLimits(address bridge, uint256 change) internal {
        uint256 currentLimit = mintingCurrentLimitOf(bridge);
        bridges[bridge].minterParams.timestamp = block.timestamp;
        bridges[bridge].minterParams.currentLimit = currentLimit - change;
    }

    function _useBurnerLimits(address bridge, uint256 change) internal {
        uint256 currentLimit = burningCurrentLimitOf(bridge);
        bridges[bridge].burnerParams.timestamp = block.timestamp;
        bridges[bridge].burnerParams.currentLimit = currentLimit - change;
    }

    function _changeMinterLimit(address bridge, uint256 limit) internal {
        uint256 oldLimit = bridges[bridge].minterParams.maxLimit;
        uint256 currentLimit = mintingCurrentLimitOf(bridge);
        bridges[bridge].minterParams.maxLimit = limit;
        bridges[bridge].minterParams.currentLimit = _calculateNewCurrentLimit(limit, oldLimit, currentLimit);
        bridges[bridge].minterParams.ratePerSecond = limit / _DURATION;
        bridges[bridge].minterParams.timestamp = block.timestamp;
    }

    function _changeBurnerLimit(address bridge, uint256 limit) internal {
        uint256 oldLimit = bridges[bridge].burnerParams.maxLimit;
        uint256 currentLimit = burningCurrentLimitOf(bridge);
        bridges[bridge].burnerParams.maxLimit = limit;
        bridges[bridge].burnerParams.currentLimit = _calculateNewCurrentLimit(limit, oldLimit, currentLimit);
        bridges[bridge].burnerParams.ratePerSecond = limit / _DURATION;
        bridges[bridge].burnerParams.timestamp = block.timestamp;
    }

    function _calculateNewCurrentLimit(uint256 limit, uint256 oldLimit, uint256 currentLimit) internal pure returns (uint256) {
        if (oldLimit > limit) {
            uint256 difference = oldLimit - limit;
            return currentLimit > difference ? currentLimit - difference : 0;
        }

        return currentLimit + (limit - oldLimit);
    }

    function _getCurrentLimit(
        uint256 currentLimit,
        uint256 maxLimit,
        uint256 timestamp,
        uint256 ratePerSecond
    ) internal view returns (uint256 limit) {
        limit = currentLimit;
        if (limit == maxLimit) {
            return limit;
        }
        if (timestamp + _DURATION <= block.timestamp) {
            return maxLimit;
        }

        uint256 calculatedLimit = limit + ((block.timestamp - timestamp) * ratePerSecond);
        return calculatedLimit > maxLimit ? maxLimit : calculatedLimit;
    }

    function _burnWithCaller(address caller, address user, uint256 amount) internal {
        if (caller != lockbox) {
            uint256 currentLimit = burningCurrentLimitOf(caller);
            if (currentLimit < amount) {
                revert IXERC20_NotHighEnoughLimits();
            }
            _useBurnerLimits(caller, amount);
        }
        _burn(user, amount);
    }

    function _mintWithCaller(address caller, address user, uint256 amount) internal {
        if (caller != lockbox) {
            uint256 currentLimit = mintingCurrentLimitOf(caller);
            if (currentLimit < amount) {
                revert IXERC20_NotHighEnoughLimits();
            }
            _useMinterLimits(caller, amount);
        }
        _mint(user, amount);
    }
}


