// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {IERC1271} from "@openzeppelin/contracts/interfaces/IERC1271.sol";

library SignatureVerifier {
    function isValidSignature(address signer, bytes32 digest, bytes memory signature) internal view returns (bool valid, address recovered) {
        ECDSA.RecoverError error;
        (recovered, error) = ECDSA.tryRecover(digest, signature);
        if (error == ECDSA.RecoverError.NoError && recovered == signer) {
            return (true, recovered);
        }

        if (signer.code.length == 0) {
            return (false, recovered);
        }

        try IERC1271(signer).isValidSignature(digest, signature) returns (bytes4 magicValue) {
            return (magicValue == IERC1271.isValidSignature.selector, recovered);
        } catch {
            return (false, recovered);
        }
    }

    function packRsv(uint8 v, bytes32 r, bytes32 s) internal pure returns (bytes memory) {
        return abi.encodePacked(r, s, v);
    }
}


