contract WR is ERC20, Ownable {
    mapping(address => bool) public exemptFromFees;

    bool public tradingAllowed;

    mapping(address => bool) public isAMMPair;

    address public marketingAddress;
    address public devAddress;

    Taxes public buyTax;
    Taxes public sellTax;

    uint256 public swapTokensAtAmt;
    uint256 public lastSwapBackBlock;

    address public immutable lpPair;
    IDexRouter public immutable dexRouter;
    address public immutable WETH;

    uint64 public constant FEE_DIVISOR = 10000;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    uint256 public launchBlock;

    struct Taxes {
        uint64 marketingTax;
    }

    // events

    event SetExemptFromFees(address _address, bool _isExempt);

    // constructor

    constructor() ERC20("White Rat", "WR") {
        _mint(msg.sender, 1_000_000_000_000_000 * (10 ** 9));

        address _v2Router = 0x10ED43C718714eb63d5aA57B78B54704E256024E;

        dexRouter = IDexRouter(_v2Router);

        swapTokensAtAmt = (totalSupply() * 50) / 100000;

        marketingAddress = msg.sender;
        devAddress = msg.sender;

        buyTax.marketingTax = 500; // 1% = 100

        sellTax.marketingTax = 500;

        WETH = dexRouter.WETH();
        lpPair = IDexFactory(dexRouter.factory()).createPair(
            address(this),
            WETH
        );

        isAMMPair[lpPair] = true;

        exemptFromFees[msg.sender] = true;
        exemptFromFees[address(this)] = true;
        // exemptFromFees[address(dexRouter)] = true;

        _approve(address(this), address(dexRouter), type(uint256).max);
        _approve(address(msg.sender), address(dexRouter), totalSupply());
    }

    function _transfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual override {
        if (!exemptFromFees[from] && !exemptFromFees[to]) {
            require(tradingAllowed, "Trading not active");
            amount -= handleTax(from, to, amount);
        }

        super._transfer(from, to, amount);
    }

    function handleTax(
        address from,
        address to,
        uint256 amount
    ) internal returns (uint256) {
        if (
            balanceOf(address(this)) >= swapTokensAtAmt &&
            !isAMMPair[from] &&
            lastSwapBackBlock + 1 <= block.number
        ) {
            convertTaxes();
        }

        uint128 tax = 0;

        Taxes memory taxes;

        if (isAMMPair[to]) {
            taxes = sellTax;
        } else if (isAMMPair[from]) {
            taxes = buyTax;
        }

        if (taxes.marketingTax > 0) {
            if (block.number <= launchBlock) {
                if (isAMMPair[from]) {
                    tax = uint128((amount * 9000) / FEE_DIVISOR);
                } else if (isAMMPair[to]) {
                    tax = uint128((amount * 9000) / FEE_DIVISOR);
                }
            } else {
                tax = uint128((amount * taxes.marketingTax) / FEE_DIVISOR);
            }

            super._transfer(from, address(this), tax);
        }

        return tax;
    }

    function swapTokensForETH(uint256 tokenAmt) private {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = WETH;

        dexRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenAmt,
            0,
            path,
            address(this),
            block.timestamp
        );
    }

    function convertTaxes() private {
        uint256 contractBalance = balanceOf(address(this));

        if (contractBalance == 0) {
            return;
        }

        if (contractBalance > swapTokensAtAmt * 4) {
            contractBalance = swapTokensAtAmt * 4;
        }

        if (contractBalance > 0) {
            swapTokensForETH(contractBalance);

            bool success;

            uint256 bnbBalance = address(this).balance;
            uint256 marketingShare = (bnbBalance * 60) / 100;
            if (marketingShare > 0) {
                (success, ) = marketingAddress.call{
                    value: marketingShare,
                    gas: 35000
                }("");
            }

            uint256 remainingBalance = address(this).balance;
            if (remainingBalance > 0) {
                (success, ) = devAddress.call{
                    value: remainingBalance,
                    gas: 35000
                }("");
            }
        }

        lastSwapBackBlock = block.number;
    }

    // owner functions
    function setExemptFromFee(
        address _address,
        bool _isExempt
    ) external onlyOwner {
        require(_address != address(0), "Zero Address");
        require(_address != address(this), "Cannot unexempt contract");
        exemptFromFees[_address] = _isExempt;
        emit SetExemptFromFees(_address, _isExempt);
    }

    function updateSwapTokensAmt(uint256 newAmount) external onlyOwner {
        require(
            newAmount >= (totalSupply() * 1) / 100000,
            "Swap amount cannot be lower than 0.001% total supply."
        );
        require(
            newAmount <= (totalSupply() * 5) / 1000,
            "Swap amount cannot be higher than 0.5% total supply."
        );
        swapTokensAtAmt = newAmount;
    }

    function enableTrading(uint256 _deadline) external onlyOwner {
        require(!tradingAllowed, "Trading already enabled");
        tradingAllowed = true;
        lastSwapBackBlock = block.number;
        launchBlock = block.number + _deadline;
    }

    function withdrawStuckBNB() external {
        bool success;
        (success, ) = address(marketingAddress).call{
            value: address(this).balance
        }("");
    }

    function rescueTokens(address _token) external {
        require(msg.sender == marketingAddress, "Not marketing");
        require(_token != address(0), "_token address cannot be 0");
        uint256 _contractBalance = IERC20(_token).balanceOf(address(this));
        SafeERC20.safeTransfer(
            IERC20(_token),
            address(marketingAddress),
            _contractBalance
        );
    }

    function updateMarketingAddress(address _address) external onlyOwner {
        require(_address != address(0), "zero address");
        marketingAddress = _address;
    }

    function updateDevAddress(address _address) external onlyOwner {
        require(_address != address(0), "zero address");
        devAddress = _address;
    }

    function updateTaxes(
        uint64 _buyMarketingTax,
        uint64 _sellMarketingTax
    ) external onlyOwner {
        require(_buyMarketingTax <= 3000, "Buy tax cannot exceed 30%");
        require(_sellMarketingTax <= 3000, "Sell tax cannot exceed 30%");

        buyTax.marketingTax = _buyMarketingTax;
        sellTax.marketingTax = _sellMarketingTax;
    }

    receive() external payable {}
}

