/**
 * @dev Implementation of ERC8004 Protocol - Next-Generation Token Distribution System
 * 
 * The first meme token adopting the ERC-8004 token standard
 * - Mint Mechanism: 10 USDC = 8,004 DOG8004 tokens
 * - Total Supply Cap: 40,020,000 DOG tokens with strategic distribution model
 */
contract DOG8004 is ERC20, Ownable, ERC2771Context {

    mapping(address => bool) public _isExcludedFromFees;
    bool public openTrade;

    // ERC8004 Protocol: USDC stablecoin contract address
    address public immutable USDC_ADDRESS;

    // ERC8004 Protocol: Exchange ratio - 10 USDC yields 8,004 DOG tokens
    uint256 public constant MINT_RATIO = 8004;
    uint256 public constant MAX_SUPPLY = 40_020_000 * 10**18;
    uint256 public constant PREMINE_AMOUNT = 24_012_000 * 10**18;
    uint256 public constant PUBLIC_MINT_CAP = 16_008_000 * 10**18;

    // ERC8004 Protocol: Real-time counter tracking all publicly minted tokens
    uint256 public publicMinted;

    // ERC8004 Protocol: USDC decimal precision (6 decimals on Base blockchain)
    uint256 public constant USDT_DECIMALS = 6;

    // ERC8004 Protocol: Treasury wallet address for USDC deposit collection
    address public treasury;

    // ERC8004 Protocol: Circuit breaker flag for emergency minting control
    bool public mintPaused;

    event Minted(address indexed user, uint256 usdtAmount, uint256 tokenAmount);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event MintPausedUpdated(bool paused);
    constructor(
        address _usdcAddress,
        address _trustedForwarder,
        address _treasury,
        address _devAddress
    ) 
        ERC20(unicode"8004 Dog", unicode"DOG8004") 
        Ownable(msg.sender)
        ERC2771Context(_trustedForwarder)
    {
        require(_usdcAddress != address(0), "Invalid USDC address");
        require(_treasury != address(0), "Invalid treasury address");
        require(_devAddress != address(0), "Invalid dev address");

        USDC_ADDRESS = _usdcAddress;
        treasury = _treasury;
        _mint(_devAddress, PREMINE_AMOUNT);
        _isExcludedFromFees[_devAddress] = true;
        _isExcludedFromFees[address(this)] = true;
    }

    function mint() external {
        require(!mintPaused, "Minting is paused");

        // ERC8004 Protocol: Fixed minting cost = 10 USDC (6 decimal precision)
        uint256 usdtAmount = 10 * 10**USDT_DECIMALS;

        // ERC8004 Protocol: Calculate token allocation (8,004 DOG tokens per 10 USDC)
        uint256 tokenAmount = (1 * 10**USDT_DECIMALS * MINT_RATIO * 10**decimals()) / (10**USDT_DECIMALS);

        require(publicMinted + tokenAmount <= PUBLIC_MINT_CAP, "Exceeds public mint cap");

        require(totalSupply() + tokenAmount <= MAX_SUPPLY, "Exceeds max supply");

        address user = _msgSender();

        IERC20 usdt = IERC20(USDC_ADDRESS);
        require(
            usdt.transferFrom(user, treasury, usdtAmount),
            "USDC transfer failed"
        );

        _mint(user, tokenAmount);

        publicMinted += tokenAmount;

        emit Minted(user, usdtAmount, tokenAmount);
    }

    function batchSetExcludedFromFees(address[] calldata accounts, bool status) external onlyOwner {
        for (uint256 i = 0; i < accounts.length; i++) {
            _isExcludedFromFees[accounts[i]] = status;
        }
    }
    function startTrade() external onlyOwner{
        openTrade = true;
    }
    function waitForStartTrade() external onlyOwner{
        openTrade = false;
    }

    function _update(address from, address to, uint256 amount) internal override {
        if (!openTrade){
            if (from != address(0) && to != address(0)) {
                require(_isExcludedFromFees[from] || _isExcludedFromFees[to], "tx not allowed");
            }
        }
        super._update(from, to, amount);
    }

    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "Invalid treasury address");
        address oldTreasury = treasury;
        treasury = _treasury;
        emit TreasuryUpdated(oldTreasury, _treasury);
    }

    function setMintPaused(bool _paused) external onlyOwner {
        mintPaused = _paused;
        emit MintPausedUpdated(_paused);
    }

    function _msgSender() internal view override(Context, ERC2771Context) returns (address) {
        return ERC2771Context._msgSender();
    }

    function _msgData() internal view override(Context, ERC2771Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength() internal view override(Context, ERC2771Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }
}

