        return TokenLib.domainSeparator(name);
    }

    function permit(
        address issuer,
        address spender,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        token.permit(name, issuer, spender, value, deadline, v, r, s);
    }

    function nonces(address account) external view returns (uint256) {
        return token.nonces[account];
    }
}


