pragma solidity 0.8.26;

/*
    Zipcoin · $ZC
    A community token inspired by the zipcoin of Vitalik Buterin's novel "Snowmoon".
    Not affiliated with Vitalik Buterin, the Ethereum Foundation, or the zipcoin.cash project.

    One transaction does everything (see LaunchOnce at the bottom):
      1. creates $ZC: 1,000,000,000 tokens, plain ERC-20, no tax in the token, no owner, no mint
      2. if there is a reserve, it goes into a vesting contract (ZipVesting): it unlocks slowly, in public,
         and nobody can take it out faster, not even the dev
      3. opens the $ZC / ETH pool on Uniswap v4 (1 % fee, no hooks) at the chosen start price
      4. puts every other token into that pool, on the token side only: buyers bring the ETH

    THE VERIDIAN SALES TAX
    Every trade pays the pool's 1 % fee. Nobody can change where it goes: the payees and their shares
    are fixed forever when this contract is created.
      - the ETH part is split between the payees (e.g. dev / fire / prize), in public, on every collect
      - the $ZC part is burned: it goes straight to the dead address

    The liquidity can never be removed: this contract has no function for it.
*/

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract Zipcoin is ERC20 {
    constructor(address to, uint256 supply) ERC20("zipcoin", "zc") {
        _mint(to, supply);
    }
}

struct PoolKey {
    address currency0;   // native ETH = address(0)
    address currency1;   // $ZC
    uint24 fee;
    int24 tickSpacing;
    address hooks;
}

struct ModifyLiquidityParams {
    int24 tickLower;
    int24 tickUpper;
    int256 liquidityDelta;
    bytes32 salt;
}

interface IPoolManager {
    function initialize(PoolKey memory key, uint160 sqrtPriceX96) external returns (int24 tick);
    function unlock(bytes calldata data) external returns (bytes memory);
    function modifyLiquidity(PoolKey memory key, ModifyLiquidityParams memory params, bytes calldata hookData)
        external returns (int256 callerDelta, int256 feesAccrued);
    function sync(address currency) external;
    function settle() external payable returns (uint256 paid);
    function take(address currency, address to, uint256 amount) external;
