/// The reserve, if any. Nothing unlocks during the cliff; after it, the reserve unlocks a little every second,
/// evenly over `duration` (no lump at the end of the cliff). Only ever pays the beneficiary. No owner, no early exit.
contract ZipVesting {
    ERC20 public immutable token;
    address public immutable beneficiary;
    uint64 public immutable start;
    uint64 public immutable cliff;      // nothing unlocks before start + cliff
    uint64 public immutable duration;   // after the cliff, everything unlocks evenly over this time
    uint256 public released;

    event Released(uint256 amount);

    constructor(ERC20 _token, address _beneficiary, uint64 _cliff, uint64 _duration) {
        require(_beneficiary != address(0), "beneficiary");
        require(_duration > 0, "schedule");
        token = _token;
        beneficiary = _beneficiary;
        start = uint64(block.timestamp);
        cliff = _cliff;
        duration = _duration;
    }

    function vested() public view returns (uint256) {
        uint256 total = token.balanceOf(address(this)) + released;
        uint256 t = block.timestamp;
        uint256 from = uint256(start) + cliff;
        if (t <= from) return 0;
        if (t >= from + duration) return total;
        return (total * (t - from)) / duration;
    }

    function releasable() public view returns (uint256) { return vested() - released; }

    /// Anyone may call it; the tokens only ever go to the beneficiary.
    function release() external {
        uint256 amount = releasable();
        require(amount > 0, "nothing yet");
        released += amount;
        require(token.transfer(beneficiary, amount), "transfer");
        emit Released(amount);
    }
}

contract ZipLaunch {
    uint256 public constant SUPPLY = 1_000_000_000 ether;
    uint24 public constant FEE = 10_000;          // 1 %
    int24 public constant TICK_SPACING = 200;
    int24 public constant MIN_TICK = -887_200;    // lowest tick usable with spacing 200
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    IPoolManager public immutable poolManager;
    Zipcoin public immutable token;
    int24 public immutable startTick;
    uint128 public immutable liquidity;
    address public immutable deployer;
    uint256 public immutable reserve;
    uint160 public immutable sqrtStart;

    // the ETH part of the fee, fixed forever
    address[] internal _payees;
    uint16[] internal _bps;                       // shares in basis points, sum = 10,000

    bool public launched;
    address public reserveHolder;                 // the vesting contract (or nobody, if there is no reserve)

    event Launched(address token, address reserveHolder, uint256 reserve, uint256 inPool, int24 startTick, uint128 liquidity);
    event FeesCollected(uint256 eth, uint256 tokensBurned);
    event FeePaid(address indexed payee, uint256 eth);

    constructor(IPoolManager _poolManager, uint256 _reserve, int24 _startTick, address[] memory payees_, uint16[] memory bps_) {
        require(_reserve < SUPPLY / 5, "reserve");    // at most 20 %, and then only vested
        require(_startTick % TICK_SPACING == 0 && _startTick > MIN_TICK + TICK_SPACING && _startTick < 887_200, "tick");
        require(payees_.length > 0 && payees_.length <= 5 && payees_.length == bps_.length, "payees");
        uint256 sum;
        for (uint256 i; i < payees_.length; i++) {
            require(payees_[i] != address(0) && bps_[i] > 0, "payee");
            sum += bps_[i];
        }
        require(sum == 10_000, "shares");
        _payees = payees_;
        _bps = bps_;

        deployer = msg.sender;
        poolManager = _poolManager;
        reserve = _reserve;
        startTick = _startTick;
        token = new Zipcoin(address(this), SUPPLY);

        uint160 s = sqrtPriceAtTick(_startTick);
        sqrtStart = s;
        uint256 inPool = SUPPLY - _reserve - 1 ether;     // 1 token of headroom for rounding, burned after
        uint256 L = (inPool << 96) / (uint256(s) - uint256(sqrtPriceAtTick(MIN_TICK)));
        require(L > 0 && L < type(uint128).max, "liquidity");
        liquidity = uint128(L);
    }

    function payees() external view returns (address[] memory, uint16[] memory) { return (_payees, _bps); }

    /// Called once, in the same transaction that created this contract (see LaunchOnce below).
    function launch(address _reserveHolder) external {
        require(msg.sender == deployer && !launched, "once");
        launched = true;
        if (reserve > 0) {
            require(_reserveHolder != address(0), "reserve holder");
            reserveHolder = _reserveHolder;
            require(token.transfer(_reserveHolder, reserve), "reserve transfer");
        }
        int24 tickNow = poolManager.initialize(_key(address(token)), sqrtStart);
        require(tickNow == startTick, "start price");
        poolManager.unlock(abi.encode(uint8(1)));
        uint256 left = token.balanceOf(address(this));
        if (left > 0) require(token.transfer(DEAD, left), "burn");
        emit Launched(address(token), _reserveHolder, reserve, SUPPLY - reserve - left, startTick, liquidity);
    }

    /// Collects the pool's fees: the ETH is split between the fixed payees, the $ZC is burned. Anyone may call it.
    function collect() external {
        poolManager.unlock(abi.encode(uint8(2)));
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        require(msg.sender == address(poolManager), "pool manager only");
        uint8 action = abi.decode(data, (uint8));
        PoolKey memory key = _key(address(token));
        if (action == 1) {
            (int256 delta,) = poolManager.modifyLiquidity(
                key, ModifyLiquidityParams(MIN_TICK, startTick, int256(uint256(liquidity)), bytes32(0)), "");
            int128 a0 = int128(delta >> 128);
            int128 a1 = int128(delta);
            require(a0 == 0, "no ETH needed");
            require(a1 < 0, "tokens owed");
            poolManager.sync(address(token));
            require(token.transfer(address(poolManager), uint256(uint128(-a1))), "pay");
            poolManager.settle();
        } else if (action == 2) {
            (int256 delta,) = poolManager.modifyLiquidity(
                key, ModifyLiquidityParams(MIN_TICK, startTick, 0, bytes32(0)), "");
            int128 a0 = int128(delta >> 128);
            int128 a1 = int128(delta);
            uint256 eth = a0 > 0 ? uint256(uint128(a0)) : 0;
            uint256 tok = a1 > 0 ? uint256(uint128(a1)) : 0;
            if (eth > 0) {
                uint256 paid;
                uint256 n = _payees.length;
                for (uint256 i; i < n; i++) {
                    // the last payee gets the rounding remainder, so every wei is paid out
                    uint256 part = i == n - 1 ? eth - paid : (eth * _bps[i]) / 10_000;
                    paid += part;
                    if (part > 0) { poolManager.take(address(0), _payees[i], part); emit FeePaid(_payees[i], part); }
                }
            }
            if (tok > 0) poolManager.take(address(token), DEAD, tok);
            emit FeesCollected(eth, tok);
        }
        return "";
    }

    function poolKey() external view returns (PoolKey memory) { return _key(address(token)); }

    function _key(address t) internal pure returns (PoolKey memory) {
        return PoolKey(address(0), t, FEE, TICK_SPACING, address(0));
    }

    /// Uniswap's TickMath.getSqrtPriceAtTick (same constants), returns sqrt(1.0001^tick) * 2^96
    function sqrtPriceAtTick(int24 tick) public pure returns (uint160) {
        unchecked {
            uint256 absTick = tick < 0 ? uint256(-int256(tick)) : uint256(int256(tick));
            require(absTick <= 887_272, "T");
            uint256 ratio = absTick & 0x1 != 0 ? 0xfffcb933bd6fad37aa2d162d1a594001 : 0x100000000000000000000000000000000;
            if (absTick & 0x2 != 0) ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
            if (absTick & 0x4 != 0) ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
            if (absTick & 0x8 != 0) ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
            if (absTick & 0x10 != 0) ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
            if (absTick & 0x20 != 0) ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
            if (absTick & 0x40 != 0) ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
            if (absTick & 0x80 != 0) ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
            if (absTick & 0x100 != 0) ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
            if (absTick & 0x200 != 0) ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
            if (absTick & 0x400 != 0) ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
            if (absTick & 0x800 != 0) ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
            if (absTick & 0x1000 != 0) ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
            if (absTick & 0x2000 != 0) ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
            if (absTick & 0x4000 != 0) ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
            if (absTick & 0x8000 != 0) ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
            if (absTick & 0x10000 != 0) ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
            if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
            if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
            if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;
            if (tick > 0) ratio = type(uint256).max / ratio;
            return uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
        }
    }
}

/// Deployed once. Its constructor creates the launcher, the reserve vesting (if any) and launches,
/// all in the same transaction, so nobody can touch the token or the pool before it is open at the right price.
contract LaunchOnce {
    ZipLaunch public immutable launcher;
    ZipVesting public immutable vesting;

    constructor(
        IPoolManager poolManager,
        int24 startTick,
        address[] memory payees,
        uint16[] memory bps,
        uint256 reserve,
        address reserveBeneficiary,
        uint64 cliff,
        uint64 duration
    ) {
        ZipLaunch l = new ZipLaunch(poolManager, reserve, startTick, payees, bps);
        ZipVesting v;
        if (reserve > 0) v = new ZipVesting(l.token(), reserveBeneficiary, cliff, duration);
        l.launch(address(v));
        launcher = l;
        vesting = v;
    }
}


