        _revokeRole(ALLOWED_TRANSFER_ROLE, admin);
        _revokeRole(SUPERVISED_TRANSFER_ADMIN_ROLE, admin);
        _revokeRole(SUPERVISED_TRANSFER_MANAGER_ROLE, admin);
