contract TaggerToken is ERC20, ReentrancyGuard, BasicAccessControl, UseSigner {
    uint public constant MODE_NORMAL = 0;
    uint public constant MODE_TRANSFER_RESTRICTED = 1;
    uint public constant MODE_TRANSFER_CONTROLLED = 2;
    uint public _mode;

    constructor() ERC20("Tagger", "TAG") UseSigner(SIGNER) {
        _mode = MODE_TRANSFER_RESTRICTED;
        grantOperator(OPERATOR);
    }

    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual override {
        super._beforeTokenTransfer(from, to, amount);
        if (_mode == MODE_TRANSFER_RESTRICTED) {
            revert("Token: Transfer is restricted");
        }
        if (_mode == MODE_TRANSFER_CONTROLLED) {
            require(from == owner() || to == owner(), "Token: Invalid transfer");
        }
    }

    address public constant PANCAKE_POSITION_MANAGER = 0x46A15B0b27311cedF172AB29E4f4766fbE7F4364;
    address public constant WBNB = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;
    address public constant LP_LOCKER = 0x25c9C4B56E820e0DEA438b145284F02D9Ca9Bd52;
    address public constant OPERATOR = 0x74d86638f359bDfF6EC55d78A97F294747f8f5B3;
    address public constant SIGNER = 0x6F3F71e803D5F59Af4C1D7dAE7d442EF548D4A0f;
    address public constant RESERVE_RECIPIENT = 0x67A7573Feebe0057c49eb445F338d83bD91CAFcB;

    bytes32 public constant CLAIM_PREFIX = keccak256("CLAIM");
    uint256 public constant MAX_SUPPLY = 400 * 10**27;
    uint256 public constant LIQUIDITY = 20 * 10**27;
    uint256 public constant RESERVE = 300 * 10**27;
    uint256 public constant AMOUNT_BNB = 70 * 10**18;

    uint256 public _positionId;
    uint256 public _lockId;

    mapping(address => bool) public _claims;
    mapping(address => bool) public _feeCollectors;
    bool public _launched;

    event TokenClaimed(address account);

    using Bytes for bytes;

    function claim(uint256 amount, uint256 time, bytes memory signature) public {
        require(_launched, "Not launched");
        require(block.timestamp - time < 90, "Expired");

        address account = _msgSender();
        require(!_claims[account], "Claimed");

        bytes memory data;
        data = data.concat(CLAIM_PREFIX);
        data = data.concat(account);
        data = data.concat(amount);
        data = data.concat(time);
        SignatureVerifier.verify(signer(), signature, data);

        _mint(account, amount);
        _claims[account] = true;
        emit TokenClaimed(account);
    }

    function launch(uint160 sqrtPriceX96) public onlyOperator {
        require(!_launched, "Launched");
        _launched = true;

        _mode = MODE_NORMAL;

        _mint(RESERVE_RECIPIENT, RESERVE);

        _mint(address(this), LIQUIDITY);
        _approve(address(this), PANCAKE_POSITION_MANAGER, LIQUIDITY);
        _positionId = addLiquidity(address(this), WBNB, LIQUIDITY, AMOUNT_BNB, sqrtPriceX96);

        if (getChainId() == 56) {
            IERC721(PANCAKE_POSITION_MANAGER).approve(LP_LOCKER, _positionId);
            _lockId = IUniV3LPLocker(LP_LOCKER).lock(
                INonfungiblePositionManager(PANCAKE_POSITION_MANAGER),
                _positionId,
                address(this),
                address(this),
                block.timestamp + (86400 * 3650),
                "DEFAULT");
        }
    }

    function addLiquidity(address tokenAddr, address quoteAddr,
        uint256 tokenAmt, uint256 quoteAmt, uint160 sqrtPriceX96) internal returns (uint256 nftId) {
        (address token0, address token1, uint256 amount0, uint256 amount1) =
            sortTokens(tokenAddr, quoteAddr, tokenAmt, quoteAmt);

        INonfungiblePositionManager mgr = INonfungiblePositionManager(PANCAKE_POSITION_MANAGER);
        mgr.createAndInitializePoolIfNecessary(token0, token1, 500, sqrtPriceX96);

        INonfungiblePositionManager.MintParams memory params = INonfungiblePositionManager.MintParams({
            token0: token0,
            token1: token1,
            fee: 500,
            tickLower: -887270,
            tickUpper: 887270,
            amount0Desired: amount0,
            amount1Desired: amount1,
            amount0Min: 0,
            amount1Min: 0,
            recipient: address(this),
            deadline: block.timestamp + 60
        });

        if (quoteAddr == WBNB) {
            (nftId,,,) = mgr.mint{value: quoteAmt}(params);
        } else {
            (nftId,,,) = mgr.mint(params);
        }
    }

    function sortTokens(address tokenA, address tokenB, uint256 amountA, uint256 amountB)
        public pure returns (address token0, address token1, uint256 amount0, uint256 amount1) {
        require(tokenA != tokenB, 'Identical address');
        (token0, token1, amount0, amount1) = tokenA < tokenB ?
            (tokenA, tokenB, amountA, amountB) : (tokenB, tokenA, amountB, amountA);
        require(token0 != address(0), 'Zero address');
    }

    function getChainId() public view returns (uint) {
        uint256 id;
        assembly { id := chainid() }
        return id;
    }

    function setFeeCollector(address account, bool enabled) public onlyOwner {
        _feeCollectors[account] = enabled;
    }

    function collectFees(address recipient, uint128 amount0Max, uint128 amount1Max)
        external nonReentrant
        returns (uint256 amount0, uint256 amount1, uint256 fee0, uint256 fee1)
    {
        require(_feeCollectors[_msgSender()], "Not allowed");

        (amount0, amount1, fee0, fee1) = IUniV3LPLocker(LP_LOCKER).collect(
            _lockId,
            recipient,
            amount0Max,
            amount1Max
        );
    }

    receive() external payable {}

    function withdrawEth(address to, uint256 amount) public onlyOwner {
        Address.sendValue(payable(to), amount);
    }
}

