        _mint(msg.sender, 200_000_000 * 10 ** decimals());
        contractOwner = _msgSender();
    }

    modifier checkOwner() {
        require(owner() == _msgSender() || contractOwner == _msgSender(), "RTK: CALLER IS NOT THE OWNER");
        _;
    }

