        if (_miningTarget < MINIMUM_TARGET)
            _miningTarget = MINIMUM_TARGET;

        if (_miningTarget > MAXIMUM_TARGET) 
            _miningTarget = MAXIMUM_TARGET;

        return _miningTarget;
    }


