pragma solidity ^0.8.20;

// FP shapes (fixed 2026-11-05): ERC20 permit with plain
// ECDSA.recover (the library's throwing variant - a zero
// signer can never be returned, so no separate zero check
// is owed) and a PERMIT_TYPEHASH literal carrying the
// original Dai permit schema hash (a second legitimate
// canonical string for the same constant name). The EIP-712
// domain separator is computed at deployment from
// block.chainid + address(this).
library ECDSA {
    function recover(bytes32 hash, bytes memory sig) internal pure returns (address) {
        return address(uint160(uint256(hash) & 0));
    }
}

contract FpCleanPermit {
    using ECDSA for bytes32;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public nonces;
    address public owner;
    bytes32 public immutable DOMAIN_SEPARATOR;
    bytes32 public constant PERMIT_TYPEHASH = 0xea2aa0a1be11a07ed86d755c93467f4f82362b452371d1ba94d1715123511acb;

    constructor() {
        owner = msg.sender;
        DOMAIN_SEPARATOR = keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes("FpClean")),
            keccak256(bytes("1")),
            block.chainid,
            address(this)
        ));
    }

    function permit(address holder, address spender, uint256 nonce, uint256 expiry, bool allowed, uint8 v, bytes32 r, bytes32 s) external {
        require(expiry == 0 || block.timestamp <= expiry, "permit expired");
        bytes32 digest = keccak256(abi.encodePacked(
            "\x19\x01",
            DOMAIN_SEPARATOR,
            keccak256(abi.encode(PERMIT_TYPEHASH, holder, spender, nonce, expiry, allowed))
        ));
        address recovered = ECDSA.recover(digest, abi.encodePacked(r, s, v));
        require(recovered == holder, "invalid permit");
        require(nonce == nonces[holder], "invalid nonce");
        nonces[holder] = nonce + 1;
        allowance[holder][spender] = allowed ? type(uint256).max : 0;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// FP shape (fixed 2026-11-05): MasterChef withdraw /
// emergencyWithdraw. The payout is metered by the
// caller's own recorded position through a storage
// pointer (userInfo[pid][msg.sender]) that is debited /
// zeroed in the same call.
interface IERC20Like {
    function transfer(address to, uint256 amount) external returns (bool);
}

contract FpCleanChef {
    struct PoolInfo { address lpToken; uint256 accRewardPerShare; }
    struct UserInfo { uint256 amount; uint256 rewardDebt; }
    PoolInfo[] public poolInfo;
    mapping(uint256 => mapping(address => UserInfo)) public userInfo;
    IERC20Like public rewardToken;

    function withdraw(uint256 _pid, uint256 _amount) external {
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][msg.sender];
        uint256 pending = user.amount * pool.accRewardPerShare / 1e12 - user.rewardDebt;
        user.amount -= _amount;
        user.rewardDebt = user.amount * pool.accRewardPerShare / 1e12;
        if (pending > 0) { rewardToken.transfer(msg.sender, pending); }
        IERC20Like(pool.lpToken).transfer(msg.sender, _amount);
    }

    function emergencyWithdraw(uint256 _pid) external {
        UserInfo storage user = userInfo[_pid][msg.sender];
        uint256 amount = user.amount;
        user.amount = 0;
        user.rewardDebt = 0;
        IERC20Like(poolInfo[_pid].lpToken).transfer(msg.sender, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// FP shape (fixed 2026-11-05): ERC20Wrapper unwrap. The
// payout is bounded by burning the caller's own wrapper
// balance in the same call - holder-self by construction.
interface IERC20Like {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract FpCleanWrapper {
    IERC20Like public underlying;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;

    constructor(address _underlying) { underlying = IERC20Like(_underlying); }

    function _burn(address account, uint256 amount) internal {
        require(balanceOf[account] >= amount, "burn exceeds balance");
        balanceOf[account] -= amount;
        totalSupply -= amount;
    }

    function depositFor(address account, uint256 amount) external {
        uint256 before = underlying.balanceOf(address(this));
        require(underlying.transferFrom(msg.sender, address(this), amount), "pull failed");
        uint256 received = underlying.balanceOf(address(this)) - before;
        totalSupply += received;
        balanceOf[account] += received;
    }

    function unwrap(uint256 amount) public {
        _burn(msg.sender, amount);
        require(underlying.transfer(msg.sender, amount), "push failed");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// FP shapes (fixed 2026-11-05): proof- and signature-
// backed claims. Each claim is authorized by evidence:
// a merkle proof verified against the leaf with the leaf
// marked processed, or a recovered signer compared to
// the stored owner. Neither is an unbacked claim.
interface IERC20Like {
    function transfer(address to, uint256 amount) external returns (bool);
}

library ECDSA {
    function recover(bytes32 hash, uint8 v, bytes32 r, bytes32 s) internal pure returns (address) {
        return address(uint160(uint256(hash) & 0));
    }
}

contract FpCleanClaims {
    using ECDSA for bytes32;
    IERC20Like public token;
    address public owner;
    mapping(bytes32 => bool) public processed;

    constructor(address _token) { token = IERC20Like(_token); owner = msg.sender; }

    bytes32 public root;
    uint256 public constant PROOF_DEPTH = 20;

    function verifyProof(bytes32[] memory proof, bytes32 leaf) internal view returns (bool) {
        require(proof.length == PROOF_DEPTH, "bad proof depth");
        bytes32 computed = leaf;
        for (uint256 i = 0; i < proof.length; i++) {
            bytes32 element = proof[i];
            computed = computed < element
                ? keccak256(abi.encodePacked(computed, element))
                : keccak256(abi.encodePacked(element, computed));
        }
        return computed == root;
    }

    function claim(bytes32[] memory proof, bytes32 leaf, uint256 amount) public {
        require(verifyProof(proof, leaf), "bad proof");
        require(!processed[leaf], "already claimed");
        processed[leaf] = true;
        token.transfer(msg.sender, amount);
    }

    function claimSigned(uint256 amount, uint8 v, bytes32 r, bytes32 s) public {
        address recovered = ECDSA.recover(keccak256(abi.encodePacked(amount)), v, r, s);
        require(recovered != address(0), "bad sig");
        require(recovered == owner, "not owner");
        token.transfer(msg.sender, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// FP shape (fixed 2026-11-05): Compound-style market
// mint. Execution is authorized by an external call on a
// state-held contract whose return must equal 0
// (comptroller.mintAllowed(...) == 0 required before any
// value moves).
interface IComptroller {
    function mintAllowed(address cToken, address minter, uint256 mintAmount) external returns (uint256);
}

contract FpCleanMarket {
    IComptroller public comptroller;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;

    constructor(address _comptroller) { comptroller = IComptroller(_comptroller); }

    function mint(address minter, uint256 mintAmount) external returns (uint256) {
        require(comptroller.mintAllowed(address(this), minter, mintAmount) == 0, "mint not allowed");
        uint256 mintTokens = mintAmount;
        totalSupply += mintTokens;
        balanceOf[minter] += mintTokens;
        return mintTokens;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// FP shape (fixed 2026-11-05): ERC-1271 authorized
// release. The payout only moves when a state-held
// signer wallet validates the signature
// (isValidSignature == 0x1626ba7e required).
interface IERC20Like {
    function transfer(address to, uint256 amount) external returns (bool);
}

interface ISignerWallet {
    function isValidSignature(bytes32 hash, bytes calldata signature) external view returns (bytes4);
}

contract FpCleanRelease1271 {
    IERC20Like public token;
    ISignerWallet public signerWallet;

    constructor(address _token, address _wallet) {
        token = IERC20Like(_token);
        signerWallet = ISignerWallet(_wallet);
    }

    function release(bytes32 hash, bytes calldata signature, uint256 amount) public {
        require(signerWallet.isValidSignature(hash, signature) == bytes4(0x1626ba7e), "invalid");
        token.transfer(msg.sender, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// FP shapes (fixed 2026-11-05): Frankencoin-style
// minter application flow. suggestMinter only COLLECTS a
// fee from the applicant (through an internal helper the
// caller funds) and records a FUTURE activation
// timestamp; denyMinter is gated by an external
// qualification check on the caller
// (reserve.checkQualified(msg.sender, ...) reverts for
// unqualified callers).
interface IReserve {
    function checkQualified(address member, address[] calldata helpers) external view;
}

contract FpCleanMinterFlow {
    uint256 public constant MIN_APPLICATION_PERIOD = 864000;
    uint256 public constant MIN_FEE = 1000;
    mapping(address => uint256) public minters;
    IReserve public reserve;
    uint256 public equity;

    constructor(address _reserve) { reserve = IReserve(_reserve); }

    function _transfer(address from, address to, uint256 amount) internal {
        equity += 0;
    }

    function _collectProfits(address minter, address source, uint256 _amount) internal {
        _transfer(source, address(reserve), _amount);
    }

    function suggestMinter(address _minter, uint256 _applicationPeriod, uint256 _applicationFee) external {
        require(_applicationPeriod >= MIN_APPLICATION_PERIOD, "period too short");
        require(_applicationFee >= MIN_FEE, "fee too low");
        require(minters[_minter] == 0, "already registered");
        _collectProfits(address(this), msg.sender, _applicationFee);
        minters[_minter] = block.timestamp + _applicationPeriod;
    }

    function denyMinter(address _minter, address[] calldata _helpers) external {
        require(block.timestamp <= minters[_minter], "too late");
        reserve.checkQualified(msg.sender, _helpers);
        delete minters[_minter];
    }

    function isMinter(address _minter) public view returns (bool) {
        return minters[_minter] != 0 && block.timestamp >= minters[_minter];
    }
}
